/**
 * Seed script: Load sample journal entries into Supabase
 * Story 2.4: Supabase Migration
 *
 * ⚠️ DEVELOPMENT ONLY - DO NOT USE IN PRODUCTION
 * This script uses a fixed prototype user ID for local testing.
 * In production, use authenticated user IDs from Supabase Auth.
 *
 * Usage: source .env.local && npx tsx scripts/seed-sample-journal-entries.ts
 */

import { sampleJournalEntries } from '../src/data/sampleEntries'
import { createClient } from '@supabase/supabase-js'

// Fixed user ID for prototype phase (DEVELOPMENT ONLY)
// TODO Story 2.4.1: Update this script to accept user_id as parameter
const PROTOTYPE_USER_ID = '00000000-0000-0000-0000-000000000000'

async function seedSampleJournalEntries() {
  // Initialize Supabase client with service role key to bypass RLS
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
  const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY

  if (!supabaseUrl || !supabaseServiceKey) {
    console.error('❌ Missing Supabase environment variables')
    console.error('   NEXT_PUBLIC_SUPABASE_URL:', supabaseUrl ? 'Set' : 'Missing')
    console.error('   SUPABASE_SERVICE_ROLE_KEY:', supabaseServiceKey ? 'Set' : 'Missing')
    console.error('\n⚠️  Note: SUPABASE_SERVICE_ROLE_KEY is required for seeding')
    console.error('   Get it from: https://supabase.com/dashboard/project/otyvmmgakowcdsxehwox/settings/api')
    process.exit(1)
  }

  const supabase = createClient(supabaseUrl, supabaseServiceKey, {
    auth: {
      persistSession: false // Prevent session caching on server
    }
  })

  console.log('🌱 Starting sample journal entry seeding...')
  console.log(`   User ID: ${PROTOTYPE_USER_ID}`)
  console.log(`   Entries to seed: ${sampleJournalEntries.length}`)

  // Check if entries already exist
  const { count } = await supabase
    .from('notes')
    .select('id', { count: 'exact', head: true })
    .eq('user_id', PROTOTYPE_USER_ID)
    .eq('note_type', 'journal-entry')

  if (count && count > 0) {
    console.log(`\n⚠️  Found ${count} existing journal entries for prototype user`)
    console.log('   Skipping seed to avoid duplicates')
    console.log('   To re-seed, delete existing entries first')
    return
  }

  // Convert sample entries to Supabase note format
  // Note: Don't use entry.id as Supabase will auto-generate UUIDs
  const notesToInsert = sampleJournalEntries.map(entry => ({
    user_id: PROTOTYPE_USER_ID,
    title: `Journal Entry - ${entry.date}`,
    content: entry.content,
    note_type: 'journal-entry',
    is_pinned: false,
    metadata: {
      journalDate: entry.date,
      isSample: entry.isSample,
      originalId: entry.id // Preserve original ID in metadata for reference
    },
    created_at: entry.lastModified,
    updated_at: entry.lastModified
  }))

  // Insert in batches (Supabase handles up to 1000 per insert)
  const BATCH_SIZE = 100
  let inserted = 0

  for (let i = 0; i < notesToInsert.length; i += BATCH_SIZE) {
    const batch = notesToInsert.slice(i, i + BATCH_SIZE)

    const { data, error } = await supabase
      .from('notes')
      .insert(batch)
      .select()

    if (error) {
      console.error(`\n❌ Error inserting batch ${i / BATCH_SIZE + 1}:`, error)
      process.exit(1)
    }

    inserted += data.length
    console.log(`   ✓ Inserted batch ${i / BATCH_SIZE + 1}: ${data.length} entries`)
  }

  console.log(`\n✅ Successfully seeded ${inserted} sample journal entries`)
  console.log(`   You can now test ontology extraction with real Supabase data`)
}

// Run the seed script
seedSampleJournalEntries()
  .then(() => {
    console.log('\n🎉 Seeding complete!')
    process.exit(0)
  })
  .catch((error) => {
    console.error('\n❌ Seeding failed:', error)
    process.exit(1)
  })

/**
 * API Route: Extract ontology from notes using GPT-5-mini
 * Story 2.4: AI Personal Ontology Extraction
 */

import { NextRequest, NextResponse } from 'next/server'
import OpenAI from 'openai'
import { Note } from '@/types/note'
import {
  buildExtractionPrompt,
  parseExtractionResult,
  ExtractionResult
} from '@/utils/ontologyPrompts'

// Initialize OpenAI client only if API key is available
const openai = process.env.OPENAI_API_KEY
  ? new OpenAI({
      apiKey: process.env.OPENAI_API_KEY
    })
  : null

export async function POST(request: NextRequest) {
  try {
    // 0. Check if OpenAI is configured
    if (!openai) {
      return NextResponse.json(
        {
          success: false,
          error: 'OpenAI API key not configured',
          details: 'Please set OPENAI_API_KEY environment variable'
        },
        { status: 500 }
      )
    }

    // 1. Parse request body
    const body = await request.json()
    const { notes } = body as { notes: Note[] }

    // 2. Validation
    if (!notes || !Array.isArray(notes)) {
      return NextResponse.json(
        { success: false, error: 'Notes array required' },
        { status: 400 }
      )
    }

    if (notes.length === 0) {
      return NextResponse.json(
        {
          success: true,
          message: 'No notes to analyze',
          counts: { values: 0, beliefs: 0, aims: 0 }
        },
        { status: 200 }
      )
    }

    if (notes.length < 5) {
      return NextResponse.json(
        {
          success: false,
          error: 'Need at least 5 notes for meaningful extraction'
        },
        { status: 400 }
      )
    }

    // 3. Limit to 20 notes for cost control
    const notesToAnalyze = notes.slice(0, 20)

    // 4. Build prompt
    const prompt = buildExtractionPrompt(notesToAnalyze)

    // 5. Call OpenAI GPT-5-mini using Responses API
    const response = await openai.responses.create({
      model: 'gpt-5-mini',
      input: prompt,
      reasoning: {
        effort: 'medium' // Balanced for philosophical analysis
      }
    })

    // Fix: gpt-5-mini returns empty output_text with Responses API
    // Extract text from response.output instead
    let responseText = response.output_text

    if (!responseText && response.output) {
      // Concatenate all output_text chunks from message content
      // GPT-5-mini may split response into multiple chunks
      const textChunks: string[] = []

      for (const item of response.output) {
        if (item.type === 'message' && item.content) {
          // Collect all text content in message (type is 'output_text', not 'text')
          for (const contentItem of item.content) {
            if (contentItem.type === 'output_text' && 'text' in contentItem) {
              textChunks.push(contentItem.text)
            }
          }
        }
      }

      // Concatenate all chunks
      responseText = textChunks.join('')
    }

    if (!responseText) {
      throw new Error('No response from OpenAI (empty output_text and no message items)')
    }

    // 6. Parse extraction result
    const extraction: ExtractionResult = parseExtractionResult(responseText)

    // 7. Return success response
    return NextResponse.json({
      success: true,
      extraction,
      counts: {
        values: extraction.values.length,
        beliefs: extraction.beliefs.length,
        aims: extraction.aims.length
      }
    })
  } catch (error) {
    console.error('Extraction failed:', error)

    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'

    return NextResponse.json(
      {
        success: false,
        error: 'Extraction failed',
        details: errorMessage
      },
      { status: 500 }
    )
  }
}

