'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { getNoteById, updateNote } from '@/lib/notes'
import { Note, getNoteDisplayTitle } from '@/types/note'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { ArrowLeft } from 'lucide-react'
import { OntologyCardViewer } from '@/components/notes/OntologyCardViewer'
import { useAuth } from '@/contexts/AuthContext'

interface AimsContent {
  todos: string
  goals: string
}

export default function NoteEditPage({ params }: { params: Promise<{ id: string }> }) {
  const router = useRouter()
  const { user } = useAuth()
  const [note, setNote] = useState<Note | null>(null)
  const [content, setContent] = useState('')
  const [aimsContent, setAimsContent] = useState<AimsContent>({ todos: '', goals: '' })
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    if (!user) return

    const userId = user.id // Capture user.id for closure

    async function loadNote() {
      const resolvedParams = await params

      // Get note from Supabase
      const loadedNote = await getNoteById(resolvedParams.id, userId)

      if (loadedNote) {
        setNote(loadedNote)

        // Support both old (type) and new (noteType) field names during migration
        const noteType = 'type' in loadedNote ? (loadedNote as { type: string }).type : loadedNote.noteType
        if (noteType === 'aims' || noteType === 'ontology-aim') {
          try {
            const parsed = JSON.parse(loadedNote.content)
            setAimsContent(parsed)
          } catch {
            setAimsContent({ todos: '', goals: '' })
          }
        } else {
          setContent(loadedNote.content)
        }
      }
      setIsLoading(false)
    }
    loadNote()
  }, [params, user])

  const handleSave = async () => {
    if (!note || !user) return

    // Support both old (type) and new (noteType) field names during migration
    const noteType = 'type' in note ? (note as { type: string }).type : note.noteType
    const newContent = (noteType === 'aims' || noteType === 'ontology-aim')
      ? JSON.stringify(aimsContent)
      : content

    const updated = await updateNote(note.id, { content: newContent }, user.id)
    if (updated) {
      setNote(updated)
    }
  }

  const handleBack = () => {
    // Return to Ontology page for ontology notes, Notes page for others
    const noteType = 'type' in note! ? (note as { type: string }).type : note!.noteType
    const isOntology = noteType === 'values' || noteType === 'beliefs' || noteType === 'aims' ||
      noteType === 'ontology-value' || noteType === 'ontology-belief' || noteType === 'ontology-aim'

    if (isOntology) {
      router.push('/ontology')
    } else {
      router.push('/notes')
    }
  }

  if (isLoading) {
    return (
      <div className="max-w-3xl mx-auto p-6">
        <p className="text-muted-foreground">Loading...</p>
      </div>
    )
  }

  if (!note) {
    return (
      <div className="max-w-3xl mx-auto p-6">
        <div className="mb-6">
          <Button variant="ghost" onClick={() => router.push('/notes')} className="gap-2">
            <ArrowLeft className="h-4 w-4" />
            Back to Notes
          </Button>
        </div>
        <div className="text-center py-12">
          <h2 className="text-2xl font-semibold mb-2">Note Not Found</h2>
          <p className="text-muted-foreground">This note could not be found.</p>
        </div>
      </div>
    )
  }

  // Check if this is an AI-populated ontology note (read-only)
  // Support both old (type) and new (noteType) field names during migration
  const noteType = 'type' in note ? (note as { type: string }).type : note.noteType
  const isOntologyNote = noteType === 'values' || noteType === 'beliefs' || noteType === 'aims' ||
    noteType === 'ontology-value' || noteType === 'ontology-belief' || noteType === 'ontology-aim'
  const backButtonLabel = isOntologyNote ? 'Back to Ontology' : 'Back to Notes'

  return (
    <div className="max-w-3xl mx-auto p-6">
      {/* Header with Back Button */}
      <div className="mb-6 flex items-center justify-between">
        <Button variant="ghost" onClick={handleBack} className="gap-2">
          <ArrowLeft className="h-4 w-4" />
          {backButtonLabel}
        </Button>
        {!isOntologyNote && (
          <Button onClick={handleSave} size="sm">
            Save
          </Button>
        )}
      </div>

      {/* Note Title */}
      <h1 className="text-3xl font-bold mb-6">{getNoteDisplayTitle(note)}</h1>

      {/* Ontology note description */}
      {isOntologyNote && (
        <div className="bg-yellow-50 dark:bg-yellow-950/30 border border-yellow-200 dark:border-yellow-800 rounded-md px-4 py-3 mb-6">
          <p className="text-sm text-yellow-900 dark:text-yellow-100">
            This note is automatically updated as you write in your journal.
          </p>
        </div>
      )}

      {/* Editor Content */}
      <div className="space-y-6">
        {isOntologyNote ? (
          // Use OntologyCardViewer for Values, Beliefs, Aims
          <div className="min-h-[400px] p-6 rounded-md border bg-muted/30">
            <OntologyCardViewer note={note} />
          </div>
        ) : (
          // Editable for regular notes
          <Textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder={`Write your ${note.title.toLowerCase()} here...`}
            className="min-h-[400px] resize-none"
            onBlur={handleSave}
          />
        )}
      </div>

      {/* Footer Instructions */}
      {!isOntologyNote && (
        <div className="mt-8 text-sm text-muted-foreground">
          <p>Changes are auto-saved when you click outside the text area or click Save.</p>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import { Sidebar } from '@/components/layout/Sidebar'
import { NotesPage } from '@/components/notes/NotesPage'
import { AppHeader } from '@/components/layout/AppHeader'

export default function NotesRoute() {
  const [activeSection, setActiveSection] = useState('notes')
  const router = useRouter()

  const handleSectionChange = (section: string) => {
    setActiveSection(section)
    if (section === 'journal') {
      router.push('/')
    } else if (section === 'ontology') {
      router.push('/ontology')
    } else if (section !== 'notes') {
      router.push('/')
    }
  }

  return (
    <div className="min-h-screen bg-background">
      <Sidebar activeSection={activeSection} onSectionChange={handleSectionChange} />
      <main className="lg:pl-64">
        <div className="flex min-h-screen flex-col">
          <AppHeader />
          <div className="flex-1">
            <NotesPage />
          </div>
        </div>
      </main>
    </div>
  )
}

'use client'

import { Suspense, useState } from 'react'
import { useRouter } from 'next/navigation'
import { Sidebar } from '@/components/layout/Sidebar'
import { OntologyPage } from '@/components/ontology/OntologyPage'
import { AppHeader } from '@/components/layout/AppHeader'

export default function OntologyRoute() {
  const [activeSection, setActiveSection] = useState('ontology')
  const router = useRouter()

  const handleSectionChange = (section: string) => {
    setActiveSection(section)
    if (section === 'journal') {
      router.push('/')
    } else if (section === 'notes') {
      router.push('/notes')
    } else if (section !== 'ontology') {
      router.push('/')
    }
  }

  return (
    <div className="min-h-screen bg-background">
      <Sidebar activeSection={activeSection} onSectionChange={handleSectionChange} />
      <main className="lg:pl-64">
        <div className="flex min-h-screen flex-col">
          <AppHeader />
          <div className="flex-1">
            <Suspense fallback={<div className="max-w-5xl mx-auto p-6">Loading...</div>}>
              <OntologyPage />
            </Suspense>
          </div>
        </div>
      </main>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { Sidebar } from '@/components/layout/Sidebar'
import { JournalStream } from '@/components/journal/JournalStream'
import { AppHeader } from '@/components/layout/AppHeader'

export default function Home() {
  const [activeSection, setActiveSection] = useState('journal')
  const router = useRouter()

  useEffect(() => {
    const handleNavigateToNotes = () => {
      setActiveSection('notes')
    }

    window.addEventListener('navigate-to-notes', handleNavigateToNotes)
    return () => window.removeEventListener('navigate-to-notes', handleNavigateToNotes)
  }, [])

  const handleSectionChange = (section: string) => {
    setActiveSection(section)
    if (section === 'notes') {
      router.push('/notes')
    } else if (section === 'ontology') {
      router.push('/ontology')
    }
  }

  const renderContent = () => {
    switch (activeSection) {
      case 'journal':
        return <JournalStream />
      case 'feedback':
        return <div className="p-6 text-center text-muted-foreground">Feedback feature coming soon...</div>
      case 'articles':
        return <div className="p-6 text-center text-muted-foreground">Articles feature coming soon...</div>
      case 'meets':
        return <div className="p-6 text-center text-muted-foreground">Meets feature coming soon...</div>
      case 'karma':
        return <div className="p-6 text-center text-muted-foreground">Karma feature coming soon...</div>
      default:
        return <JournalStream />
    }
  }

  return (
    <div className="min-h-screen bg-background">
      <Sidebar activeSection={activeSection} onSectionChange={handleSectionChange} />
      <main className="lg:pl-64">
        <div className="flex min-h-screen flex-col">
          <AppHeader />
          <div className="flex-1">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  )
}

'use client'

import { useState } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'

interface AuthFormsProps {
  mode: 'signin' | 'signup'
  onToggleMode: () => void
}

export function AuthForms({ mode, onToggleMode }: AuthFormsProps) {
  const { signIn, signUp, resetPassword } = useAuth()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [loading, setLoading] = useState(false)
  const [message, setMessage] = useState('')
  const [showResetPassword, setShowResetPassword] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setMessage('')

    try {
      if (showResetPassword) {
        const { error } = await resetPassword(email)
        if (error && typeof error === 'object' && 'message' in error) {
          setMessage((error as { message: string }).message)
        } else {
          setMessage('Password reset email sent! Check your inbox.')
        }
      } else if (mode === 'signup') {
        const { error } = await signUp(email, password)
        if (error && typeof error === 'object' && 'message' in error) {
          setMessage((error as { message: string }).message)
        } else {
          setMessage('Check your email for the confirmation link!')
        }
      } else {
        const { error } = await signIn(email, password)
        if (error && typeof error === 'object' && 'message' in error) {
          setMessage((error as { message: string }).message)
        }
      }
    } catch {
      setMessage('An unexpected error occurred')
    } finally {
      setLoading(false)
    }
  }

  if (showResetPassword) {
    return (
      <Card className="w-full max-w-md mx-auto">
        <CardHeader>
          <CardTitle>Reset Password</CardTitle>
          <CardDescription>
            Enter your email address and we&apos;ll send you a link to reset your password.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="reset-email">Email</Label>
              <Input
                id="reset-email"
                type="email"
                placeholder="Enter your email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>

            {message && (
              <div className={`text-sm ${message.includes('sent') ? 'text-green-600' : 'text-red-600'}`}>
                {message}
              </div>
            )}

            <div className="space-y-2">
              <Button type="submit" className="w-full" disabled={loading}>
                {loading ? 'Sending...' : 'Send Reset Email'}
              </Button>
              <Button
                type="button"
                variant="ghost"
                className="w-full"
                onClick={() => setShowResetPassword(false)}
              >
                Back to Sign In
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card className="w-full max-w-md mx-auto">
      <CardHeader>
        <CardTitle>{mode === 'signup' ? 'Create Account' : 'Welcome Back'}</CardTitle>
        <CardDescription>
          {mode === 'signup'
            ? 'Create your account to start journaling with Signum'
            : 'Sign in to your Signum account'
          }
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="email">Email</Label>
            <Input
              id="email"
              type="email"
              placeholder="Enter your email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="password">Password</Label>
            <Input
              id="password"
              type="password"
              placeholder="Enter your password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              minLength={6}
            />
          </div>

          {message && (
            <div className={`text-sm ${message.includes('Check your email') ? 'text-green-600' : 'text-red-600'}`}>
              {message}
            </div>
          )}

          <div className="space-y-2">
            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? 'Loading...' : (mode === 'signup' ? 'Create Account' : 'Sign In')}
            </Button>

            {mode === 'signin' && (
              <Button
                type="button"
                variant="ghost"
                className="w-full text-sm"
                onClick={() => setShowResetPassword(true)}
              >
                Forgot your password?
              </Button>
            )}
          </div>

          <div className="text-center text-sm text-muted-foreground">
            {mode === 'signup' ? 'Already have an account?' : "Don&apos;t have an account?"}{' '}
            <Button variant="link" onClick={onToggleMode} className="p-0 h-auto">
              {mode === 'signup' ? 'Sign in' : 'Sign up'}
            </Button>
          </div>
        </form>
      </CardContent>
    </Card>
  )
}

'use client'

import { useAuth } from '@/contexts/AuthContext'
import { useEffect } from 'react'
import { useRouter } from 'next/navigation'

interface ProtectedRouteProps {
  children: React.ReactNode
  redirectTo?: string
}

export function ProtectedRoute({ children, redirectTo = '/auth' }: ProtectedRouteProps) {
  const { user, loading } = useAuth()
  const router = useRouter()

  useEffect(() => {
    if (!loading && !user) {
      router.push(redirectTo)
    }
  }, [user, loading, router, redirectTo])

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-muted-foreground">Loading...</p>
        </div>
      </div>
    )
  }

  if (!user) {
    return null
  }

  return <>{children}</>
}

'use client'

import { useTheme } from 'next-themes'
import { useEffect, useState } from 'react'
import Link from 'next/link'
import Image from 'next/image'

interface LogoProps {
  className?: string
  size?: number
}

export function Logo({ className = '', size = 40 }: LogoProps) {
  const { resolvedTheme } = useTheme()
  const [mounted, setMounted] = useState(false)

  // Avoid hydration mismatch by only rendering after mount
  useEffect(() => {
    setMounted(true)
  }, [])

  // Default to light theme during SSR/initial render
  const logoSrc = mounted && resolvedTheme === 'dark'
    ? '/logos/signum-logo-white.svg'
    : '/logos/signum-logo.svg'

  return (
    <Link
      href="/"
      className={`inline-flex items-center justify-center transition-opacity hover:opacity-80 ${className}`}
      aria-label="Signum Home"
    >
      <Image
        src={logoSrc}
        alt="Signum"
        width={size}
        height={size * 1.5} // S logo is taller than it is wide (600/400 = 3/2 ratio)
        priority
        className="object-contain"
      />
    </Link>
  )
}

'use client'

import React, { useRef, useCallback, useState, useEffect } from 'react'
import { Button } from '@/components/ui/button'
import { Bold, Italic, Underline, List, ListOrdered, Heading1, Heading2, Quote, AlignLeft, AlignCenter, AlignRight, FileText } from 'lucide-react'

interface SimpleRichEditorProps {
  value?: string
  placeholder?: string
  initialValue?: string
  onChange?: (content: string) => void
  onFocus?: () => void
  onBlur?: (e: React.FocusEvent) => void
  autoFocus?: boolean
  onMakeNote?: (selectedText: string) => void
}

export function SimpleRichEditor({
  value,
  placeholder = "Start writing your thoughts...",
  initialValue = "",
  onChange,
  onFocus,
  onBlur,
  autoFocus = false,
  onMakeNote
}: SimpleRichEditorProps) {
  const editorRef = useRef<HTMLDivElement>(null)
  const [selectedText, setSelectedText] = useState('')
  const [hasSelection, setHasSelection] = useState(false)

  const formatText = useCallback((command: string, value?: string) => {
    if (editorRef.current) {
      editorRef.current.focus()
      document.execCommand(command, false, value)

      // Trigger change event after formatting
      if (onChange) {
        const content = editorRef.current.innerHTML || ''
        onChange(content)
      }
    }
  }, [onChange])

  const insertHeading = useCallback((level: number) => {
    if (editorRef.current) {
      editorRef.current.focus()
      const selection = window.getSelection()
      if (selection && selection.rangeCount > 0) {
        const range = selection.getRangeAt(0)
        const headingElement = document.createElement(`h${level}`)
        headingElement.style.fontSize = level === 1 ? '1.5em' : '1.25em'
        headingElement.style.fontWeight = 'bold'
        headingElement.style.marginBottom = '0.5em'

        try {
          range.surroundContents(headingElement)
        } catch {
          // If can't surround, insert at cursor
          headingElement.textContent = 'Heading'
          range.insertNode(headingElement)
        }

        // Trigger change event
        if (onChange) {
          const content = editorRef.current.innerHTML || ''
          onChange(content)
        }
      }
    }
  }, [onChange])

  const insertList = useCallback((ordered: boolean) => {
    formatText(ordered ? 'insertOrderedList' : 'insertUnorderedList')
  }, [formatText])

  const setAlignment = useCallback((align: string) => {
    formatText(`justify${align.charAt(0).toUpperCase() + align.slice(1)}`)
  }, [formatText])

  const handleInput = useCallback(() => {
    if (onChange && editorRef.current) {
      const content = editorRef.current.innerHTML || ''
      onChange(content)
    }
  }, [onChange])

  const handlePaste = useCallback((e: React.ClipboardEvent) => {
    e.preventDefault()
    const text = e.clipboardData.getData('text/plain')
    document.execCommand('insertText', false, text)
  }, [])

  const handleTextSelection = useCallback(() => {
    // Add a small delay to ensure the selection has been processed
    setTimeout(() => {
      const selection = window.getSelection()

      if (selection && selection.rangeCount > 0 && !selection.isCollapsed) {
        const selectedText = selection.toString().trim()

        // Additional check: ensure the selection is within our editor
        if (selectedText.length > 0 && editorRef.current) {
          const range = selection.getRangeAt(0)
          const isWithinEditor = editorRef.current.contains(range.commonAncestorContainer)

          if (isWithinEditor) {
            setSelectedText(selectedText)
            setHasSelection(true)
            return
          }
        }
      }

      setHasSelection(false)
    }, 50)
  }, [])

  const handleMakeNoteClick = useCallback(() => {
    if (selectedText && onMakeNote) {
      onMakeNote(selectedText)
      setHasSelection(false)
      setSelectedText('')
    }
  }, [selectedText, onMakeNote])

  const handleClickOutside = useCallback((e: Event) => {
    const target = e.target as HTMLElement
    if (target && !target.closest('[contenteditable]') && !target.closest('[data-make-note-button]')) {
      setHasSelection(false)
      setSelectedText('')
    }
  }, [])

  // Set initial content when value changes
  React.useEffect(() => {
    if (editorRef.current && value !== undefined) {
      const currentContent = editorRef.current.innerHTML || ''
      if (currentContent !== value) {
        editorRef.current.innerHTML = value
      }
    }
  }, [value])

  // Auto focus
  React.useEffect(() => {
    if (autoFocus && editorRef.current) {
      editorRef.current.focus()
    }
  }, [autoFocus])

  // Selection detection and event listeners
  useEffect(() => {
    const handleSelection = () => {
      // Add a small delay to ensure selection has been processed
      setTimeout(handleTextSelection, 50)
    }

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && hasSelection) {
        setHasSelection(false)
        setSelectedText('')
      }
    }

    // Listen for selection changes more comprehensively
    document.addEventListener('mouseup', handleSelection)
    document.addEventListener('keyup', handleSelection)
    document.addEventListener('keydown', handleKeyDown)
    document.addEventListener('click', handleClickOutside)
    document.addEventListener('selectionchange', handleSelection)

    // Also listen on the editor element directly
    const editor = editorRef.current
    if (editor) {
      editor.addEventListener('mouseup', handleSelection)
      editor.addEventListener('keyup', handleSelection)
    }

    return () => {
      document.removeEventListener('mouseup', handleSelection)
      document.removeEventListener('keyup', handleSelection)
      document.removeEventListener('keydown', handleKeyDown)
      document.removeEventListener('click', handleClickOutside)
      document.removeEventListener('selectionchange', handleSelection)

      if (editor) {
        editor.removeEventListener('mouseup', handleSelection)
        editor.removeEventListener('keyup', handleSelection)
      }
    }
  }, [handleTextSelection, handleClickOutside, hasSelection])

  return (
    <div className="relative min-h-[120px] w-full border rounded-md overflow-hidden">
      {/* Formatting Toolbar */}
      <div className="flex items-center gap-1 p-2 border-b bg-muted/50 flex-wrap">
        {/* Text Formatting */}
        <div className="flex items-center gap-1 border-r pr-2 mr-2">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => formatText('bold')}
            className="h-8 w-8 p-0"
            type="button"
            title="Bold"
          >
            <Bold className="h-4 w-4" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => formatText('italic')}
            className="h-8 w-8 p-0"
            type="button"
            title="Italic"
          >
            <Italic className="h-4 w-4" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => formatText('underline')}
            className="h-8 w-8 p-0"
            type="button"
            title="Underline"
          >
            <Underline className="h-4 w-4" />
          </Button>
        </div>

        {/* Headings */}
        <div className="flex items-center gap-1 border-r pr-2 mr-2">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => insertHeading(1)}
            className="h-8 w-8 p-0"
            type="button"
            title="Heading 1"
          >
            <Heading1 className="h-4 w-4" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => insertHeading(2)}
            className="h-8 w-8 p-0"
            type="button"
            title="Heading 2"
          >
            <Heading2 className="h-4 w-4" />
          </Button>
        </div>

        {/* Lists */}
        <div className="flex items-center gap-1 border-r pr-2 mr-2">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => insertList(false)}
            className="h-8 w-8 p-0"
            type="button"
            title="Bullet List"
          >
            <List className="h-4 w-4" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => insertList(true)}
            className="h-8 w-8 p-0"
            type="button"
            title="Numbered List"
          >
            <ListOrdered className="h-4 w-4" />
          </Button>
        </div>

        {/* Alignment */}
        <div className="flex items-center gap-1 border-r pr-2 mr-2">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setAlignment('left')}
            className="h-8 w-8 p-0"
            type="button"
            title="Align Left"
          >
            <AlignLeft className="h-4 w-4" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setAlignment('center')}
            className="h-8 w-8 p-0"
            type="button"
            title="Align Center"
          >
            <AlignCenter className="h-4 w-4" />
          </Button>
          <Button
            size="sm"
            variant="ghost"
            onClick={() => setAlignment('right')}
            className="h-8 w-8 p-0"
            type="button"
            title="Align Right"
          >
            <AlignRight className="h-4 w-4" />
          </Button>
        </div>

        {/* Quote */}
        <Button
          size="sm"
          variant="ghost"
          onClick={() => formatText('indent')}
          className="h-8 w-8 p-0"
          type="button"
          title="Quote/Indent"
        >
          <Quote className="h-4 w-4" />
        </Button>

        {/* Make Note - only show when text is selected and onMakeNote is provided */}
        {hasSelection && onMakeNote && (
          <div className="flex items-center border-l pl-2 ml-2" data-make-note-button>
            <Button
              size="sm"
              variant="ghost"
              onMouseDown={(e) => {
                e.preventDefault()
                e.stopPropagation()
                handleMakeNoteClick()
              }}
              className="h-8 px-2 flex items-center gap-1"
              type="button"
              title="Create a note from selected text"
              data-make-note-button
            >
              <FileText className="h-4 w-4" />
              <span className="text-xs">Make Note</span>
            </Button>
          </div>
        )}
      </div>

      {/* Editor */}
      <div className="relative">
        <div
          ref={editorRef}
          contentEditable
          suppressContentEditableWarning={true}
          onInput={handleInput}
          onFocus={onFocus}
          onBlur={onBlur}
          onPaste={handlePaste}
          className="min-h-[120px] w-full resize-none border-0 bg-transparent p-4 text-foreground focus:outline-none focus:ring-0 text-base leading-relaxed"
          style={{ whiteSpace: 'pre-wrap' }}
        />
        {/* Placeholder */}
        {(!value && !initialValue) && (
          <div className="absolute left-4 top-4 text-muted-foreground pointer-events-none select-none text-base">
            {placeholder}
          </div>
        )}
      </div>

    </div>
  )
}

'use client'

/**
 * CBT Cognitive Distortions Helper Component
 * Story 1.8.2: Helper System Enhancement
 * Issue #18: Refactored to use HelperContainer
 *
 * Provides a progressive disclosure interface for selecting and inserting
 * CBT cognitive distortion reflection prompts into journal entries.
 *
 * Features:
 * - Unified HelperContainer wrapper
 * - Multiple selection via checkboxes
 * - Usage tracking integration
 * - Full WCAG AA accessibility compliance
 * - Blue/indigo gradient styling
 */

import { useState, useRef } from 'react'
import { Button } from '@/components/ui/button'
import { Checkbox } from '@/components/ui/checkbox'
import { CBT_DISTORTIONS, formatMultipleReflections } from '@/data/cbtDistortions'
import { createHelperUsage } from '@/lib/supabase/helpers'
import { HelperEvent } from '@/types/helper'
import { HelperContainer } from './HelperContainer'

interface CbtDistortionsProps {
  entryId: string
  userId: string
  onInsert: (text: string) => void
}

export function CbtDistortions({ entryId, userId, onInsert }: CbtDistortionsProps) {
  const [selectedDistortions, setSelectedDistortions] = useState<Set<string>>(new Set())
  const [liveRegionMessage, setLiveRegionMessage] = useState('')

  // Ref to access HelperContainer's collapse function
  const collapseHelperRef = useRef<(() => void) | null>(null)

  // Track events for usage logging
  const eventsRef = useRef<HelperEvent[]>([])

  // Helper function to add event to tracking
  const addEvent = (event: HelperEvent) => {
    eventsRef.current.push(event)
  }

  // Helper function to announce to screen readers
  const announce = (message: string) => {
    setLiveRegionMessage(message)
    // Clear after announcement
    setTimeout(() => setLiveRegionMessage(''), 1000)
  }

  // Handle expand/collapse from HelperContainer
  const handleExpandChange = (isExpanded: boolean) => {
    if (isExpanded) {
      // Track helper opened event
      addEvent({
        type: 'helper_opened',
        timestamp: new Date().toISOString(),
        data: { triggerSource: 'manual' }
      })
      announce('CBT Distortions helper expanded. 10 distortions available.')
    } else {
      announce('CBT Distortions helper collapsed')
    }
  }

  // Handle checkbox selection
  const handleSelect = (distortionId: string, distortionName: string) => {
    const newSelection = new Set(selectedDistortions)

    if (newSelection.has(distortionId)) {
      newSelection.delete(distortionId)
      announce(`Deselected ${distortionName}`)
    } else {
      newSelection.add(distortionId)
      announce(`Selected ${distortionName}`)

      // Track selection event
      addEvent({
        type: 'helper_selection',
        timestamp: new Date().toISOString(),
        data: {
          selectedCount: newSelection.size,
          selectedItems: Array.from(newSelection)
        }
      })
    }

    setSelectedDistortions(newSelection)
  }

  // Handle clear all selections
  const handleClear = () => {
    const previousCount = selectedDistortions.size
    setSelectedDistortions(new Set())

    // Track cleared event
    addEvent({
      type: 'helper_cleared',
      timestamp: new Date().toISOString(),
      data: { previousSelectionCount: previousCount }
    })

    announce('All selections cleared')
  }

  // Handle insert reflections
  const handleInsert = async () => {
    if (selectedDistortions.size === 0) return

    // Get selected distortion objects
    const selected = CBT_DISTORTIONS.filter(d => selectedDistortions.has(d.id))

    // Format reflection text
    const reflectionText = formatMultipleReflections(selected)

    // Track inserted event
    const insertedEvent: HelperEvent = {
      type: 'helper_inserted',
      timestamp: new Date().toISOString(),
      data: {
        insertedText: reflectionText,
        distortionCount: selected.length
      }
    }
    addEvent(insertedEvent)

    // Log usage to database (non-blocking)
    try {
      await createHelperUsage({
        helperType: 'cbt-distortions',
        entryId: entryId,
        selectedItems: Array.from(selectedDistortions),
        metadata: {
          events: eventsRef.current,
          selectionCount: selectedDistortions.size,
          insertedText: reflectionText,
          distortionNames: selected.map(d => d.name)
        }
      }, userId)
    } catch (error) {
      console.error('Failed to log helper usage:', error)
      // Don't block user interaction if logging fails
    }

    // Announce and callback
    announce(`Inserted ${selected.length} distortion reflections`)
    onInsert(reflectionText)

    // Reset state
    setSelectedDistortions(new Set())
    eventsRef.current = []

    // Collapse the helper after insertion
    if (collapseHelperRef.current) {
      collapseHelperRef.current()
    }
  }

  return (
    <>
      {/* Screen reader live region for announcements */}
      <div
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      >
        {liveRegionMessage}
      </div>

      <HelperContainer
        helperType="cbt-distortions"
        headerText="Have you experienced any distorted thinking today?"
        descriptionText="Select one or more and click &quot;Continue&quot; to add them to your journal."
        variant="blue"
        onExpandChange={handleExpandChange}
        collapseRef={collapseHelperRef}
        showDismiss={false}
        defaultExpanded={false}
        testId="cbt"
      >
        {/* Distortion checkboxes */}
        <div className="space-y-3 pr-2">
          {CBT_DISTORTIONS.map((distortion) => (
            <div
              key={distortion.id}
              className="flex items-start gap-3 p-3 rounded-md bg-white/50 dark:bg-gray-900/50 hover:bg-white/80 dark:hover:bg-gray-900/80 transition-colors"
            >
              <Checkbox
                id={`distortion-${distortion.id}`}
                checked={selectedDistortions.has(distortion.id)}
                onCheckedChange={() => handleSelect(distortion.id, distortion.name)}
                aria-label={`Select ${distortion.name}`}
                className="mt-1"
                data-testid={`distortion-${distortion.id}-checkbox`}
              />
              <label
                htmlFor={`distortion-${distortion.id}`}
                className="flex-1 cursor-pointer"
              >
                <div className="font-medium text-base text-blue-900 dark:text-blue-100 mb-1">
                  {distortion.name}
                </div>
                <div className="text-sm text-blue-700/80 dark:text-blue-300/80 mb-1">
                  {distortion.description}
                </div>
                <div className="text-sm text-blue-600/60 dark:text-blue-400/60 italic">
                  Example: {distortion.example}
                </div>
              </label>
            </div>
          ))}
        </div>

        {/* Action buttons */}
        <div className="flex gap-2 pt-4 border-t border-blue-200 dark:border-blue-800">
          <Button
            onClick={handleInsert}
            disabled={selectedDistortions.size === 0}
            className="bg-blue-600 hover:bg-blue-700 text-white dark:bg-blue-700 dark:hover:bg-blue-600"
            size="sm"
            data-testid="cbt-continue-button"
          >
            Continue
            {selectedDistortions.size > 0 && (
              <span className="ml-2 px-1.5 py-0.5 bg-blue-500 dark:bg-blue-800 rounded text-xs">
                {selectedDistortions.size}
              </span>
            )}
          </Button>
          <Button
            onClick={handleClear}
            disabled={selectedDistortions.size === 0}
            variant="ghost"
            size="sm"
            className="text-blue-700 hover:text-blue-900 hover:bg-blue-100 dark:text-blue-300 dark:hover:text-blue-100 dark:hover:bg-blue-900/50"
            data-testid="cbt-clear-button"
          >
            Clear
          </Button>
        </div>
      </HelperContainer>
    </>
  )
}

'use client'

/**
 * HelperContainer Component
 * Issue #18: Unified Helper Framework
 *
 * A unified container/wrapper component for all journal helpers.
 * Provides consistent:
 * - Visual structure and styling
 * - Progressive disclosure pattern (expand/collapse)
 * - Accessibility features (aria-live, keyboard navigation)
 * - Dismissal functionality (persistent via Supabase)
 *
 * Designed to wrap helper content (e.g., CBT Distortions, Reflection Prompts).
 */

import { useState, useRef, ReactNode, useEffect } from 'react'
import { Card } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { ChevronDown, ChevronUp, X } from 'lucide-react'
import { HelperType } from '@/types/helper'

export interface HelperContainerProps {
  /** Unique identifier for the helper type */
  helperType: HelperType

  /** Header text displayed when helper is collapsed */
  headerText: string

  /** Optional description text shown when expanded */
  descriptionText?: string

  /** Content to display when helper is expanded */
  children: ReactNode

  /** Callback when user dismisses the helper */
  onDismiss?: () => void

  /** Callback when helper is expanded/collapsed */
  onExpandChange?: (isExpanded: boolean) => void

  /** Ref callback to expose collapse function to parent */
  collapseRef?: React.MutableRefObject<(() => void) | null>

  /** Visual theme variant */
  variant?: 'default' | 'blue' | 'green' | 'purple'

  /** Optional CSS class name for customization */
  className?: string

  /** Test ID for Playwright tests */
  testId?: string

  /** Whether to show the dismiss button */
  showDismiss?: boolean

  /** Whether to start in expanded state */
  defaultExpanded?: boolean
}

/** Theme color mappings for different helper types */
const THEME_COLORS = {
  default: {
    card: 'bg-gradient-to-r from-gray-50 to-slate-50 border-gray-200 dark:from-gray-950/30 dark:to-slate-950/30 dark:border-gray-800',
    text: 'text-gray-900 dark:text-gray-100',
    subtext: 'text-gray-800 dark:text-gray-200',
    button: 'text-gray-700 hover:text-gray-900 hover:bg-gray-100 dark:text-gray-300 dark:hover:text-gray-100 dark:hover:bg-gray-900/50',
  },
  blue: {
    card: 'bg-gradient-to-r from-blue-50 to-indigo-50 border-blue-200 dark:from-blue-950/30 dark:to-indigo-950/30 dark:border-blue-800',
    text: 'text-blue-900 dark:text-blue-100',
    subtext: 'text-blue-800 dark:text-blue-200',
    button: 'text-blue-700 hover:text-blue-900 hover:bg-blue-100 dark:text-blue-300 dark:hover:text-blue-100 dark:hover:bg-blue-900/50',
  },
  green: {
    card: 'bg-gradient-to-r from-green-50 to-emerald-50 border-green-200 dark:from-green-950/30 dark:to-emerald-950/30 dark:border-green-800',
    text: 'text-green-900 dark:text-green-100',
    subtext: 'text-green-800 dark:text-green-200',
    button: 'text-green-700 hover:text-green-900 hover:bg-green-100 dark:text-green-300 dark:hover:text-green-100 dark:hover:bg-green-900/50',
  },
  purple: {
    card: 'bg-gradient-to-r from-purple-50 to-violet-50 border-purple-200 dark:from-purple-950/30 dark:to-violet-950/30 dark:border-purple-800',
    text: 'text-purple-900 dark:text-purple-100',
    subtext: 'text-purple-800 dark:text-purple-200',
    button: 'text-purple-700 hover:text-purple-900 hover:bg-purple-100 dark:text-purple-300 dark:hover:text-purple-100 dark:hover:bg-purple-900/50',
  },
}

export function HelperContainer({
  helperType,
  headerText,
  descriptionText,
  children,
  onDismiss,
  onExpandChange,
  collapseRef,
  variant = 'default',
  className = '',
  testId,
  showDismiss = true,
  defaultExpanded = false,
}: HelperContainerProps) {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded)
  const [liveRegionMessage, setLiveRegionMessage] = useState('')
  const exploreButtonRef = useRef<HTMLButtonElement>(null)

  const theme = THEME_COLORS[variant]

  // Expose collapse function to parent via ref
  useEffect(() => {
    if (collapseRef) {
      collapseRef.current = () => {
        setIsExpanded(false)
        announce(`${helperType} helper collapsed`)
        // Return focus to Explore button
        setTimeout(() => {
          exploreButtonRef.current?.focus()
        }, 100)
      }
    }
    return () => {
      if (collapseRef) {
        collapseRef.current = null
      }
    }
  }, [collapseRef, helperType])

  // Helper function to announce to screen readers
  const announce = (message: string) => {
    setLiveRegionMessage(message)
    // Clear after announcement
    setTimeout(() => setLiveRegionMessage(''), 1000)
  }

  // Handle expand/collapse
  const handleExpand = () => {
    const newExpandedState = !isExpanded
    setIsExpanded(newExpandedState)

    if (newExpandedState) {
      announce(`${helperType} helper expanded`)
    } else {
      announce(`${helperType} helper collapsed`)
      // Return focus to Explore button
      setTimeout(() => {
        exploreButtonRef.current?.focus()
      }, 100)
    }

    onExpandChange?.(newExpandedState)
  }

  // Handle dismiss
  const handleDismiss = () => {
    announce(`${helperType} helper dismissed`)
    onDismiss?.()
  }

  // Keyboard handlers
  const handleKeyDown = (event: React.KeyboardEvent) => {
    // Escape closes the expanded panel
    if (event.key === 'Escape' && isExpanded) {
      event.preventDefault()
      setIsExpanded(false)
      announce(`${helperType} helper collapsed`)
      exploreButtonRef.current?.focus()
    }
  }

  return (
    <div onKeyDown={handleKeyDown} className={className}>
      {/* Screen reader live region for announcements */}
      <div
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      >
        {liveRegionMessage}
      </div>

      <Card
        className={`mb-4 ${theme.card}`}
        data-testid={testId}
      >
        <div className="px-4 py-1">
          {/* Header with Explore and Dismiss buttons */}
          <div className="flex items-center justify-between">
            <span className={`font-medium text-lg ${theme.text}`}>
              {headerText}
            </span>

            <div className="flex items-center gap-2">
              <Button
                ref={exploreButtonRef}
                onClick={handleExpand}
                variant="ghost"
                size="sm"
                className={theme.button}
                aria-expanded={isExpanded}
                aria-controls={`${helperType}-panel`}
                data-testid={testId ? `${testId}-explore-button` : undefined}
              >
                {isExpanded ? (
                  <>
                    <ChevronUp className="h-4 w-4 mr-1" />
                    Collapse
                  </>
                ) : (
                  <>
                    <ChevronDown className="h-4 w-4 mr-1" />
                    Explore
                  </>
                )}
              </Button>

              {showDismiss && (
                <Button
                  onClick={handleDismiss}
                  variant="ghost"
                  size="sm"
                  className={theme.button}
                  aria-label={`Dismiss ${helperType} helper`}
                  data-testid={testId ? `${testId}-dismiss-button` : undefined}
                >
                  <X className="h-4 w-4" />
                </Button>
              )}
            </div>
          </div>

          {/* Expanded panel with helper content */}
          {isExpanded && (
            <div
              id={`${helperType}-panel`}
              data-testid={testId ? `${testId}-helper-panel` : undefined}
              className="mt-4 space-y-3 animate-in fade-in slide-in-from-top-2 duration-200"
            >
              {descriptionText && (
                <p className={`text-base ${theme.subtext} mb-4`}>
                  {descriptionText}
                </p>
              )}

              {children}
            </div>
          )}
        </div>
      </Card>
    </div>
  )
}

'use client'

import { useState, useEffect, useRef } from 'react'
import { useRouter } from 'next/navigation'
import { SimpleRichEditor } from '@/components/editor/SimpleRichEditor'
import { Card } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Calendar, BookOpen } from 'lucide-react'
import { NoteCreationModal } from '@/components/notes/NoteCreationModal'
import { NoteViewer } from '@/components/notes/NoteViewer'
import { Note } from '@/types/note'
import { createLink, getOutgoingLinks } from '@/lib/supabase/notes'
import { convertTextToLink, captureSelectionMetadata, rehydrateLinksFromMetadata } from '@/utils/textToLink'
import { getNotes, createNote, updateNote as updateNoteInDb, deleteNote } from '@/lib/notes'
import { useAuth } from '@/contexts/AuthContext'
import { toast } from 'sonner'
import { CbtDistortions } from '@/components/journal/helpers/CbtDistortions'

interface JournalEntry {
  id: string
  date: string  // YYYY-MM-DD format
  content: string
  lastModified: string
  isSample?: boolean
}

// Helper: Get today's date in local timezone as YYYY-MM-DD
function getLocalDateString(): string {
  const now = new Date()
  const year = now.getFullYear()
  const month = String(now.getMonth() + 1).padStart(2, '0')
  const day = String(now.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

export function JournalStream() {
  const router = useRouter()
  const { user } = useAuth()
  const [entries, setEntries] = useState<JournalEntry[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [editingEntryId, setEditingEntryId] = useState<string | null>(null)
  const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const [showNoteModal, setShowNoteModal] = useState(false)
  const [selectedText, setSelectedText] = useState('')
  const [currentEditingEntry, setCurrentEditingEntry] = useState<string | null>(null)
  const [showNoteViewer, setShowNoteViewer] = useState(false)
  const [viewingNoteId, setViewingNoteId] = useState<string | null>(null)
  const [noteLinkClicked, setNoteLinkClicked] = useState(false)
  const [creatingLink, setCreatingLink] = useState(false)

  // Cache editor element reference before opening modal (Phase 1 bug fix)
  const cachedEditorRef = useRef<HTMLElement | null>(null)

  useEffect(() => {
    // Load journal entries from Supabase
    async function loadEntries() {
      if (!user) {
        console.log('[JournalStream] No user, clearing entries')
        // Clear entries and reset loading state when user signs out
        setEntries([])
        setIsLoading(false)
        return
      }

      console.log('[JournalStream] Starting to load entries for user:', user.id)

      try {
        const today = getLocalDateString() // Use local date instead of UTC
        console.log('[JournalStream] Today\'s date:', today)

        // Get all notes from Supabase
        console.log('[JournalStream] Fetching notes from Supabase...')
        const allNotes = await getNotes(user.id)
        console.log('[JournalStream] Fetched notes:', allNotes.length)

        // Clean up empty journal entries older than 24 hours (Issue #10)
        const now = new Date()
        const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000)

        const emptyJournalEntries = allNotes.filter(note =>
          note.noteType === 'journal-entry' &&
          note.content.trim() === '' &&
          new Date(note.createdAt) < oneDayAgo
        )

        if (emptyJournalEntries.length > 0) {
          console.log(`[JournalStream] Cleaning up ${emptyJournalEntries.length} empty journal entries older than 24 hours`)
          await Promise.all(
            emptyJournalEntries.map(note => deleteNote(note.id, user.id))
          )
        }

        // Filter to journal entries only (excluding the ones we just deleted)
        const journalNotes = allNotes.filter(note =>
          note.noteType === 'journal-entry' &&
          !emptyJournalEntries.some(empty => empty.id === note.id)
        )

        // Convert Note format to JournalEntry format
        const journalEntries: JournalEntry[] = journalNotes.map(note => {
          // Safely handle metadata (can be null for legacy notes)
          const meta = note.metadata || {}
          const journalDate = (meta as { journalDate?: string }).journalDate
          const isSample = (meta as { isSample?: boolean }).isSample

          return {
            id: note.id,
            date: journalDate || note.createdAt.split('T')[0],
            content: note.content,
            lastModified: note.updatedAt,
            isSample: Boolean(isSample)
          }
        })

        // Check if today's entry exists
        const todayEntry = journalEntries.find(e => e.date === today)
        console.log('[JournalStream] Today entry exists?', !!todayEntry)

        let initialEntries: JournalEntry[] = journalEntries
        if (!todayEntry) {
          // Create today's entry if it doesn't exist
          console.log('[JournalStream] Creating today\'s entry...')
          const newNote = await createNote({
            title: `Journal Entry - ${today}`,
            content: '',
            noteType: 'journal-entry',
            metadata: { journalDate: today }
          }, user.id)
          console.log('[JournalStream] Created new note:', newNote.id)

          const newTodayEntry: JournalEntry = {
            id: newNote.id,
            date: today,
            content: '',
            lastModified: newNote.createdAt
          }
          initialEntries = [newTodayEntry, ...journalEntries]
        }

        console.log('[JournalStream] Setting entries:', initialEntries.length)
        setEntries(initialEntries)
        setIsLoading(false)
        console.log('[JournalStream] Load complete')

        // Phase 2: Link rehydration - run after DOM updates
        // Use setTimeout to ensure entries are rendered in DOM before rehydration
        setTimeout(async () => {
          console.log('[JournalStream] Starting link rehydration...')

          for (const entry of initialEntries) {
            try {
              // Fetch outgoing links for this entry
              const links = await getOutgoingLinks(entry.id, user.id)

              if (links.length === 0) {
                continue
              }

              console.log(`[JournalStream] Entry ${entry.id} has ${links.length} links`)

              // Find the editor element for this entry
              const editorElement = document.querySelector(
                `[data-entry-id="${entry.id}"] [contenteditable]`
              ) as HTMLElement

              if (!editorElement) {
                console.warn(`[JournalStream] Could not find editor for entry ${entry.id}`)
                continue
              }

              // Rehydrate links in this entry
              const result = rehydrateLinksFromMetadata(
                editorElement,
                links.map(link => ({
                  id: link.id,
                  targetNoteId: link.targetNoteId,
                  metadata: link.metadata
                })),
                handleLinkClick
              )

              console.log(
                `[JournalStream] Entry ${entry.id}: ${result.rehydrated} rehydrated, ${result.skipped} skipped`
              )
            } catch (error) {
              console.error(`[JournalStream] Error rehydrating links for entry ${entry.id}:`, error)
            }
          }

          console.log('[JournalStream] Link rehydration complete')
        }, 100)

      } catch (error) {
        console.error('[JournalStream] Error loading journal entries:', error)
        // Set safe fallback state - show empty array on error
        setEntries([])
        setIsLoading(false)
        // Optionally show user-facing error message
        // toast.error('Failed to load journal entries. Please refresh the page.')
      }
    }

    // Safely invoke async function
    loadEntries().catch(error => {
      console.error('Unhandled error in loadEntries:', error)
      setEntries([])
      setIsLoading(false)
    })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user?.id]) // Only re-run when user ID changes (login/logout), not on user object updates

  const handleContentChange = (entryId: string, newContent: string) => {
    // Don't override content changes while we're creating a link
    if (creatingLink) {
      return
    }

    // Get current entry to check if content actually changed
    const currentEntry = entries.find(e => e.id === entryId)
    if (currentEntry && currentEntry.content === newContent) {
      return // No change, don't trigger saves
    }

    // Clear existing timeout
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current)
    }

    // Update content immediately for responsive UI
    setEntries(prev => prev.map(entry =>
      entry.id === entryId
        ? { ...entry, content: newContent, lastModified: new Date().toISOString() }
        : entry
    ))

    // Auto-save after 2 seconds of no typing (longer delay to reduce noise)
    saveTimeoutRef.current = setTimeout(async () => {
      const previousContent = currentEntry?.content || ''

      // Save if content is non-empty OR if we're clearing previously non-empty content
      const shouldSave = newContent.trim() !== '' || previousContent.trim() !== ''

      if (shouldSave && user) {
        console.log('Auto-saving entry:', entryId)
        try {
          // Update the note in Supabase
          await updateNoteInDb(entryId, { content: newContent }, user.id)
        } catch (error) {
          console.error('Error auto-saving journal entry:', error)
        }
      }
    }, 2000)
  }

  const handleMakeNote = (selectedText: string) => {
    setSelectedText(selectedText)
    setCurrentEditingEntry(editingEntryId)

    // Phase 1 bug fix: Cache editor element BEFORE opening modal
    // Modal opening causes entry to exit edit mode, losing contenteditable
    if (editingEntryId) {
      const editorElement = document.querySelector(`[data-entry-id="${editingEntryId}"] [contenteditable]`) as HTMLElement
      cachedEditorRef.current = editorElement
      console.log('💾 Cached editor element:', !!editorElement)
    }

    setShowNoteModal(true)
  }

  const handleNoteCreated = async (note: Note) => {
    if (!currentEditingEntry || !selectedText || !user) {
      console.log('❌ Missing currentEditingEntry, selectedText, or user', { currentEditingEntry, selectedText, user: !!user })
      return
    }

    console.log('📝 Creating note link', { selectedText, noteId: note.id, entryId: currentEditingEntry })

    // Set flag to prevent content change interference
    setCreatingLink(true)

    // Phase 1 bug fix: Use cached editor ref and re-enter edit mode if needed
    let editorElement = cachedEditorRef.current

    // If cached ref is stale, try to find editor and re-enter edit mode
    if (!editorElement || !document.contains(editorElement)) {
      console.log('⚠️ Cached editor stale, re-entering edit mode')

      // Re-enter edit mode
      setEditingEntryId(currentEditingEntry)

      // Wait for edit mode to be active
      await new Promise(resolve => setTimeout(resolve, 100))

      // Try to find editor again
      editorElement = document.querySelector(`[data-entry-id="${currentEditingEntry}"] [contenteditable]`) as HTMLElement
    }

    // Hard fail with toast if editor still missing
    if (!editorElement) {
      console.error('❌ Could not find editor element after re-entry attempt')
      toast.error('Failed to create link: editor not found. Please try again.')
      setCreatingLink(false)
      cachedEditorRef.current = null
      return
    }

    try {
      // Phase 1: Capture metadata BEFORE DOM manipulation
      const metadata = captureSelectionMetadata(editorElement, selectedText)
      console.log('📊 Captured selection metadata:', metadata)

      // Phase 1: Create link in Supabase with metadata
      const link = await createLink({
        sourceNoteId: currentEditingEntry,
        targetNoteId: note.id,
        linkType: 'created_from',
        metadata: metadata || undefined
      }, user.id)
      console.log('💾 Link created in Supabase:', link)

      // Convert the selected text to a link in the DOM with linkId
      const linkCreated = convertTextToLink(editorElement, selectedText, note.id, link.id, handleLinkClick)

      if (!linkCreated) {
        console.error('❌ Failed to create link in editor')
        setCreatingLink(false)
        return
      }

      console.log('🔗 Created link in editor DOM')

      // Now read the updated HTML from the editor after the link was created
      // Wait for DOM to settle, then read the actual content
      setTimeout(() => {
        const updatedContent = editorElement.innerHTML
        console.log('📄 Read updated content from editor after link creation')

        // Update state with the content that includes the link at the correct position
        setEntries(prev => prev.map(entry => {
          if (entry.id === currentEditingEntry) {
            return { ...entry, content: updatedContent, lastModified: new Date().toISOString() }
          }
          return entry
        }))

        // Persist the linked content to Supabase
        updateNoteInDb(currentEditingEntry, { content: updatedContent }, user.id)
          .then(() => console.log('💾 Persisted link to Supabase'))
          .catch(error => console.error('Error persisting link to Supabase:', error))

        setCreatingLink(false)

        // Clear cached ref after successful link creation
        cachedEditorRef.current = null
      }, 50)
    } catch (error) {
      console.error('❌ Error creating link:', error)
      toast.error('Failed to create link. Please try again.')
      setCreatingLink(false)
      cachedEditorRef.current = null
    }
  }

  const handleLinkClick = (noteId: string) => {
    setNoteLinkClicked(true)
    setViewingNoteId(noteId)
    setShowNoteViewer(true)
    // Reset the flag after a short delay
    setTimeout(() => setNoteLinkClicked(false), 100)
  }

  const handleCloseNoteModal = () => {
    setShowNoteModal(false)
    setSelectedText('')
  }

  const handleCloseNoteViewer = () => {
    setShowNoteViewer(false)
    setViewingNoteId(null)
  }

  const handleHelperInsertion = async (entryId: string, helperText: string) => {
    if (!user) {
      return
    }

    console.log('📝 Inserting helper text', { entryId, helperText })

    // Clear any pending auto-save timeout to prevent race condition
    // If user typed then quickly inserted helper, pending timeout would overwrite helper text
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current)
      saveTimeoutRef.current = null
      console.log('⏱️ Cleared pending auto-save timeout before helper insertion')
    }

    // Set flag to prevent content change interference (same as link creation)
    setCreatingLink(true)

    try {
      // Ensure entry is in edit mode before inserting
      if (editingEntryId !== entryId) {
        console.log('⚠️ Entry not in edit mode, entering edit mode first')
        setEditingEntryId(entryId)
        // Wait for edit mode to activate and DOM to update
        await new Promise(resolve => setTimeout(resolve, 100))
      }

      // Find the editor element for this entry using DOM query
      const editorElement = document.querySelector(
        `[data-entry-id="${entryId}"] [contenteditable]`
      ) as HTMLElement

      if (!editorElement) {
        console.error('❌ Could not find editor element for entry:', entryId)
        toast.error('Failed to insert helper text: editor not found')
        setCreatingLink(false)
        return
      }

      // Read current content from DOM
      const currentContent = editorElement.innerHTML || ''

      // Prepend helper text to top (plain paragraphs)
      const updatedContent = helperText + currentContent

      // Update DOM directly
      editorElement.innerHTML = updatedContent

      // Wait for DOM to settle, then read the actual content
      setTimeout(() => {
        const finalContent = editorElement.innerHTML

        // Update state with the content that includes the helper text
        setEntries(prev => prev.map(entry => {
          if (entry.id === entryId) {
            return { ...entry, content: finalContent, lastModified: new Date().toISOString() }
          }
          return entry
        }))

        // Persist to Supabase
        updateNoteInDb(entryId, { content: finalContent }, user.id)
          .then(() => console.log('💾 Persisted helper insertion to Supabase'))
          .catch(error => console.error('Error persisting helper insertion:', error))

        setCreatingLink(false)
      }, 50)
    } catch (error) {
      console.error('❌ Error inserting helper text:', error)
      toast.error('Failed to insert helper text. Please try again.')
      setCreatingLink(false)
    }
  }

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr + 'T00:00:00') // Ensure consistent date parsing
    const today = new Date()
    today.setHours(0, 0, 0, 0)
    const yesterday = new Date(today)
    yesterday.setDate(yesterday.getDate() - 1)

    if (date.getTime() === today.getTime()) {
      return 'Today'
    } else if (date.getTime() === yesterday.getTime()) {
      return 'Yesterday'
    } else {
      return date.toLocaleDateString('en-US', {
        weekday: 'long',
        month: 'short',
        day: 'numeric',
        year: date.getFullYear() !== today.getFullYear() ? 'numeric' : undefined
      })
    }
  }

  const isToday = (dateStr: string) => {
    const today = getLocalDateString()
    return dateStr === today
  }

  return (
    <div className="max-w-4xl mx-auto p-6 space-y-6">
      {/* Accessible heading for screen readers and tests - visually hidden */}
      <h1 className="sr-only">Journal</h1>

      {/* Journal Entries - One per day */}
      <div className="space-y-4">
        {!user ? (
          <Card className="p-6">
            <div className="text-center">
              <BookOpen className="h-12 w-12 mx-auto mb-4 opacity-50 text-muted-foreground" />
              <h3 className="text-lg font-semibold mb-4">Sign in to start journaling</h3>
              <Button onClick={() => router.push('/auth')}>
                Sign In
              </Button>
            </div>
          </Card>
        ) : isLoading ? (
          <Card className="p-6">
            <div className="text-center text-muted-foreground">
              Loading your journal...
            </div>
          </Card>
        ) : null}
        {entries.map((entry) => {
          const isEditingThis = editingEntryId === entry.id
          const isTodayEntry = isToday(entry.date)

          return (
            <Card
              key={entry.id}
              data-entry-id={entry.id}
              className={`p-6 bg-card transition-all ${
                isTodayEntry ? 'border-2 border-primary/20' : ''
              } ${
                isEditingThis ? 'ring-2 ring-primary/30' : ''
              }`}
            >
              <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <Calendar className="h-3 w-3" />
                  <span className="font-medium">{formatDate(entry.date)}</span>
                  {entry.isSample && (
                    <span className="text-xs px-2 py-1 bg-muted rounded-md ml-2">Sample</span>
                  )}
                </div>
                {entry.content && (
                  <span className="text-xs text-muted-foreground">
                    Last saved: {new Date(entry.lastModified).toLocaleTimeString('en-US', {
                      hour: 'numeric',
                      minute: '2-digit',
                      hour12: true
                    })}
                  </span>
                )}
              </div>

              {/* CBT Distortions Helper (only on today's entry) */}
              {isTodayEntry && user && (
                <CbtDistortions
                  entryId={entry.id}
                  userId={user.id}
                  onInsert={(helperText) => handleHelperInsertion(entry.id, helperText)}
                />
              )}

              <div
                onClick={() => setEditingEntryId(entry.id)}
                className="cursor-text hover:bg-muted/30 p-2 rounded-md transition-colors"
              >
                {isEditingThis ? (
                  <SimpleRichEditor
                    value={entry.content}
                    placeholder={isTodayEntry ? "What's on your mind today? Start writing..." : "Continue your thoughts..."}
                    onChange={(content) => handleContentChange(entry.id, content)}
                    onBlur={(e) => {
                      // Don't exit edit mode if the user clicked on a note link
                      if (noteLinkClicked) {
                        return
                      }
                      const relatedTarget = e.relatedTarget as HTMLElement
                      if (relatedTarget && relatedTarget.closest('a[data-note-id]')) {
                        return
                      }
                      setEditingEntryId(null)
                    }}
                    onMakeNote={handleMakeNote}
                    onFocus={() => {
                      // Phase 2: Link rehydration from Supabase will be implemented here
                      // For now, links already in HTML remain functional
                    }}
                    autoFocus
                  />
                ) : (
                  <div className="min-h-[100px]">
                    {entry.content ? (
                      <div
                        className="text-base leading-relaxed prose prose-sm max-w-none"
                        dangerouslySetInnerHTML={{ __html: entry.content }}
                        onClick={(e) => {
                          // Handle link clicks in read-only mode
                          const target = e.target as HTMLElement

                          // Find the closest link element (in case click is on nested content)
                          const linkElement = target.closest('a[data-note-id]') as HTMLElement

                          console.log('🖱️ Read-only click:', {
                            targetTag: target.tagName,
                            linkElement: !!linkElement,
                            noteId: linkElement?.getAttribute('data-note-id')
                          })

                          if (linkElement) {
                            console.log('✅ Valid link click in read-only mode')
                            e.preventDefault()
                            e.stopPropagation()
                            const noteId = linkElement.getAttribute('data-note-id')
                            if (noteId) {
                              console.log('📱 Opening note viewer for:', noteId)
                              handleLinkClick(noteId)
                            }
                          }
                        }}
                      />
                    ) : (
                      <p className="text-muted-foreground italic">
                        {isTodayEntry ? "Click here to start today's entry..." : "Click to add to this day's entry..."}
                      </p>
                    )}
                  </div>
                )}
              </div>
            </Card>
          )
        })}
      </div>

      {/* Note Creation Modal */}
      <NoteCreationModal
        isOpen={showNoteModal}
        onClose={handleCloseNoteModal}
        initialTitle={selectedText}
        onNoteCreated={handleNoteCreated}
      />

      {/* Note Viewer Modal */}
      <NoteViewer
        isOpen={showNoteViewer}
        onClose={handleCloseNoteViewer}
        noteId={viewingNoteId}
      />
    </div>
  )
}

