'use client'

import { useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { Button } from '@/components/ui/button'
import { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider } from '@/components/ui/tooltip'
import { Logo } from '@/components/branding/Logo'
import { Menu, X, BookOpen, StickyNote, Target, MessageCircle, FileText, Users, Coins, ChevronLeft, ChevronRight } from 'lucide-react'

interface SidebarProps {
  activeSection: string
  onSectionChange: (section: string) => void
}

export function Sidebar({ activeSection, onSectionChange }: SidebarProps) {
  // Manual collapse state with localStorage persistence
  const [manuallyCollapsed, setManuallyCollapsed] = useState<boolean | null>(null)
  // Mobile drawer state
  const [mobileDrawerOpen, setMobileDrawerOpen] = useState(false)
  const { user, signOut } = useAuth()

  // Load manual collapse preference from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('sidebar-collapsed')
    if (saved !== null) {
      setManuallyCollapsed(saved === 'true')
    } else {
      setManuallyCollapsed(null) // Let responsive behavior handle it
    }
  }, [])

  // Save manual preference to localStorage
  const toggleManualCollapse = () => {
    const newState = manuallyCollapsed === null ? true : !manuallyCollapsed
    setManuallyCollapsed(newState)
    localStorage.setItem('sidebar-collapsed', String(newState))
  }

  // Determine if sidebar should be collapsed based on manual preference
  // If no manual preference, let Tailwind responsive classes handle it
  const isCollapsed = manuallyCollapsed ?? false

  const sections = [
    { id: 'journal', label: 'Journal', icon: BookOpen },
    { id: 'notes', label: 'Notes', icon: StickyNote },
    { id: 'ontology', label: 'Ontology', icon: Target },
    { id: 'feedback', label: 'Feedback', icon: MessageCircle },
    { id: 'articles', label: 'Articles', icon: FileText },
    { id: 'meets', label: 'Meets', icon: Users },
    { id: 'karma', label: 'Karma', icon: Coins },
  ]

  return (
    <>
      {/* Mobile Hamburger Button - Only visible on mobile (<768px) */}
      <div className="fixed top-4 left-4 z-50 md:hidden">
        <Button
          variant="outline"
          size="sm"
          onClick={() => setMobileDrawerOpen(!mobileDrawerOpen)}
          className="bg-background/80 backdrop-blur-sm"
        >
          <Menu className="h-5 w-5" />
        </Button>
      </div>

      {/* Manual Toggle Button - Desktop/Tablet only (>=768px) */}
      <Button
        variant="ghost"
        size="sm"
        onClick={toggleManualCollapse}
        className={`
          hidden md:flex
          fixed top-4 z-50
          transition-all duration-300 ease-in-out
          ${
            manuallyCollapsed !== null
              ? (isCollapsed ? 'left-[72px]' : 'left-[248px]')
              : 'md:left-[72px] xl:left-[248px]'
          }
        `}
        aria-label={isCollapsed ? "Expand sidebar" : "Collapse sidebar"}
      >
        {
          manuallyCollapsed !== null
            ? (isCollapsed ? <ChevronRight className="h-5 w-5" /> : <ChevronLeft className="h-5 w-5" />)
            : <><ChevronRight className="h-5 w-5 xl:hidden" /><ChevronLeft className="h-5 w-5 hidden xl:block" /></>
        }
      </Button>

      {/* Sidebar - Desktop/Tablet (>=768px): Always visible, width changes */}
      <div className={`
        hidden md:flex
        fixed left-0 top-0 h-dvh bg-sidebar border-r border-sidebar-border z-40
        flex-col
        transition-all duration-300 ease-in-out
        ${
          // Manual override takes precedence
          manuallyCollapsed !== null
            ? (isCollapsed ? 'w-20' : 'w-64')
            // No manual override: responsive behavior
            : 'md:w-20 xl:w-64'
        }
      `}>
        {/* Responsive behavior:
          - Desktop (>=1280px xl:): Default to w-64 (full), unless manually collapsed -> w-20
          - Tablet (768px-1279px md:): Default to w-20 (icon-only), unless manually expanded -> w-64
          - Manual toggle overrides automatic responsive behavior
        */}
        <div className={`
          h-full flex flex-col
          transition-all duration-300 ease-in-out
          ${
            manuallyCollapsed !== null
              ? (isCollapsed ? 'p-4' : 'p-6')
              : 'md:p-4 xl:p-6'
          }
        `}>
          {/* Header */}
          <div className={`
            mb-8 flex
            ${
              manuallyCollapsed !== null
                ? (isCollapsed ? 'justify-center' : 'justify-start')
                : 'md:justify-center xl:justify-start'
            }
          `}>
            <Logo size={
              manuallyCollapsed !== null
                ? (isCollapsed ? 28 : 32)
                : 32 // Keep consistent size, responsive handled by breakpoints
            } className={manuallyCollapsed === null ? 'md:w-7 md:h-7 xl:w-8 xl:h-8' : ''} />
          </div>

          {/* Navigation */}
          <TooltipProvider delayDuration={300}>
            <nav className="space-y-2 flex-1">
              {sections.map((section) => {
                const Icon = section.icon
                const isActive = activeSection === section.id

                const button = (
                  <Button
                    key={section.id}
                    variant={isActive ? "secondary" : "ghost"}
                    className={`
                      w-full transition-all duration-300
                      ${
                        manuallyCollapsed !== null
                          ? (isCollapsed ? 'justify-center px-2' : 'justify-start')
                          : 'md:justify-center md:px-2 xl:justify-start xl:px-4'
                      }
                      ${
                        isActive
                          ? 'bg-sidebar-accent text-sidebar-accent-foreground'
                          : 'text-sidebar-foreground hover:bg-sidebar-accent/50'
                      }
                    `}
                    onClick={() => onSectionChange(section.id)}
                    aria-label={section.label}
                  >
                    <Icon className={`
                      h-5 w-5
                      ${
                        manuallyCollapsed !== null
                          ? (isCollapsed ? '' : 'mr-3')
                          : 'xl:mr-3'
                      }
                    `} />
                    <span className={`
                      text-lg
                      transition-opacity duration-300
                      ${
                        manuallyCollapsed !== null
                          ? (isCollapsed ? 'hidden opacity-0 w-0' : 'opacity-100')
                          : 'md:hidden md:opacity-0 md:w-0 xl:block xl:opacity-100 xl:w-auto'
                      }
                    `}>
                      {section.label}
                    </span>
                  </Button>
                )

                // Wrap button in tooltip if in icon-only mode
                return (
                  <Tooltip key={section.id}>
                    <TooltipTrigger asChild>
                      {button}
                    </TooltipTrigger>
                    <TooltipContent
                      side="right"
                      sideOffset={8}
                      className={`
                        ${
                          manuallyCollapsed !== null
                            ? (isCollapsed ? '' : 'hidden')
                            : 'xl:hidden'
                        }
                      `}
                    >
                      {section.label}
                    </TooltipContent>
                  </Tooltip>
                )
              })}
            </nav>
          </TooltipProvider>

          {/* User Status - Hidden when collapsed or on tablet */}
          {(manuallyCollapsed !== null ? !isCollapsed : true) && (
            <div className={`
              border-t border-sidebar-border pt-4 mt-auto
              ${manuallyCollapsed === null ? 'md:hidden xl:block' : ''}
            `}>
              {user ? (
                <div className="space-y-3">
                  <div>
                    <p className="text-base font-medium text-sidebar-foreground">Signed in as:</p>
                    <p className="text-base text-sidebar-foreground/60 truncate">{user.email}</p>
                  </div>
                  <Button variant="outline" size="sm" onClick={signOut} className="w-full">
                    Sign Out
                  </Button>
                </div>
              ) : (
                <div className="space-y-3">
                  <Button variant="outline" size="sm" asChild className="w-full">
                    <a href="/auth">Sign Up</a>
                  </Button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Mobile Drawer - Only on mobile (<768px) */}
      <div className={`
        md:hidden
        fixed left-0 top-0 h-dvh bg-sidebar border-r border-sidebar-border z-40
        w-64
        transition-transform duration-300 ease-in-out
        ${mobileDrawerOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6 h-full flex flex-col">
          {/* Header */}
          <div className="mb-8 flex justify-between items-center">
            <Logo size={32} />
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setMobileDrawerOpen(false)}
            >
              <X className="h-5 w-5" />
            </Button>
          </div>

          {/* Navigation */}
          <nav className="space-y-2 flex-1">
            {sections.map((section) => {
              const Icon = section.icon
              const isActive = activeSection === section.id

              return (
                <Button
                  key={section.id}
                  variant={isActive ? "secondary" : "ghost"}
                  className={`w-full justify-start ${
                    isActive
                      ? 'bg-sidebar-accent text-sidebar-accent-foreground'
                      : 'text-sidebar-foreground hover:bg-sidebar-accent/50'
                  }`}
                  onClick={() => {
                    onSectionChange(section.id)
                    setMobileDrawerOpen(false)
                  }}
                >
                  <Icon className="h-5 w-5 mr-3" />
                  <span className="text-lg">{section.label}</span>
                </Button>
              )
            })}
          </nav>

          {/* User Status */}
          <div className="border-t border-sidebar-border pt-4 mt-auto">
            {user ? (
              <div className="space-y-3">
                <div>
                  <p className="text-base font-medium text-sidebar-foreground">Signed in as:</p>
                  <p className="text-base text-sidebar-foreground/60 truncate">{user.email}</p>
                </div>
                <Button variant="outline" size="sm" onClick={signOut} className="w-full">
                  Sign Out
                </Button>
              </div>
            ) : (
              <div className="space-y-3">
                <Button variant="outline" size="sm" asChild className="w-full">
                  <a href="/auth">Sign Up</a>
                </Button>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Mobile Overlay - Only visible when drawer is open */}
      {mobileDrawerOpen && (
        <div
          className="md:hidden fixed inset-0 bg-black/50 z-30"
          onClick={() => setMobileDrawerOpen(false)}
        />
      )}
    </>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { SimpleRichEditor } from '@/components/editor/SimpleRichEditor'
import { createNote } from '@/lib/notes'
import { Note } from '@/types/note'
import { Save, X } from 'lucide-react'
import { useAuth } from '@/contexts/AuthContext'

interface NoteCreationModalProps {
  isOpen: boolean
  onClose: () => void
  initialTitle: string
  onNoteCreated?: (note: Note) => void
}

export function NoteCreationModal({
  isOpen,
  onClose,
  initialTitle,
  onNoteCreated
}: NoteCreationModalProps) {
  const { user } = useAuth()
  const [title, setTitle] = useState(initialTitle)
  const [content, setContent] = useState('')
  const [isSaving, setIsSaving] = useState(false)

  // Update title when initialTitle changes
  useEffect(() => {
    if (isOpen && initialTitle) {
      setTitle(initialTitle)
    }
  }, [isOpen, initialTitle])

  const handleSave = async () => {
    if (!title.trim() || !user) return

    setIsSaving(true)
    try {
      const newNote = await createNote({
        title: title.trim(),
        content: content.trim(),
        noteType: 'custom' // Notes created from UI are custom notes
      }, user.id)

      onNoteCreated?.(newNote)
      handleClose()
    } catch (error) {
      console.error('Error creating note:', error)
    } finally {
      setIsSaving(false)
    }
  }

  const handleClose = () => {
    setTitle('')
    setContent('')
    setIsSaving(false)
    onClose()
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      handleClose()
    } else if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
      e.preventDefault()
      handleSave()
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent
        className="max-w-3xl max-h-[85vh] flex flex-col"
        onKeyDown={handleKeyDown}
      >
        <DialogHeader className="flex-shrink-0 pb-4">
          <DialogTitle className="text-2xl">Create New Note</DialogTitle>
        </DialogHeader>

        <div className="flex-1 flex flex-col gap-4 overflow-y-auto pr-2">
          <div className="flex-shrink-0 space-y-2">
            <Label htmlFor="note-title">Title</Label>
            <Input
              id="note-title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Enter note title..."
              className="text-lg font-medium"
              autoFocus
            />
          </div>

          <div className="flex-1 flex flex-col min-h-[400px]">
            <div className="flex-1 overflow-y-auto">
              <SimpleRichEditor
                value={content}
                placeholder="Start writing your note content..."
                onChange={setContent}
              />
            </div>
          </div>
        </div>

        <DialogFooter className="flex-shrink-0 pt-4">
          <Button
            variant="outline"
            onClick={handleClose}
            disabled={isSaving}
            className="flex items-center gap-2"
          >
            <X className="h-4 w-4" />
            Cancel
          </Button>
          <Button
            onClick={handleSave}
            disabled={!title.trim() || isSaving}
            className="flex items-center gap-2"
          >
            <Save className="h-4 w-4" />
            {isSaving ? 'Creating...' : 'Create Note'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { getRegularNotes } from '@/lib/notes'
import { Note } from '@/types/note'
import { RegularNoteCard } from './RegularNoteCard'
import { useAuth } from '@/contexts/AuthContext'

export function NotesPage() {
  const { user } = useAuth()
  const [regularNotes, setRegularNotes] = useState<Note[]>([])

  const loadNotes = async () => {
    if (!user) return

    // Get all regular notes from Supabase (sorted by createdAt DESC)
    const allNotes = await getRegularNotes(user.id)

    setRegularNotes(allNotes)
  }

  useEffect(() => {
    if (!user) {
      // Clear notes when user signs out to prevent data leakage
      setRegularNotes([])
      return
    }

    loadNotes()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user])

  return (
    <div className="max-w-5xl mx-auto p-6 space-y-8">
      <section>
        {regularNotes.length === 0 ? (
          <div className="text-center py-12 text-muted-foreground">
            <p>No notes yet. Create notes from your journal entries.</p>
          </div>
        ) : (
          <div className="space-y-4">
            {regularNotes.map((note) => (
              <RegularNoteCard key={note.id} note={note} />
            ))}
          </div>
        )}
      </section>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { SimpleRichEditor } from '@/components/editor/SimpleRichEditor'
import { Note } from '@/types/note'
import { getNoteById, updateNote, deleteNote } from '@/lib/notes'
import { Calendar, Edit, Save, X, Trash2 } from 'lucide-react'
import { useAuth } from '@/contexts/AuthContext'

interface NoteViewerProps {
  isOpen: boolean
  onClose: () => void
  noteId: string | null
  onNoteUpdated?: (note: Note) => void
  onNoteDeleted?: (noteId: string) => void
}

export function NoteViewer({
  isOpen,
  onClose,
  noteId,
  onNoteUpdated,
  onNoteDeleted
}: NoteViewerProps) {
  const { user } = useAuth()
  const [note, setNote] = useState<Note | null>(null)
  const [isEditing, setIsEditing] = useState(false)
  const [editTitle, setEditTitle] = useState('')
  const [editContent, setEditContent] = useState('')
  const [isSaving, setIsSaving] = useState(false)
  const [isDeleting, setIsDeleting] = useState(false)

  useEffect(() => {
    if (noteId && isOpen && user) {
      let isActive = true

      getNoteById(noteId, user.id).then(foundNote => {
        // Only update state if this effect is still active (noteId hasn't changed)
        if (isActive) {
          if (foundNote) {
            setNote(foundNote)
            setEditTitle(foundNote.title)
            setEditContent(foundNote.content || '')
          } else {
            setNote(null)
          }
        }
      })

      // Cleanup function to prevent stale updates
      return () => {
        isActive = false
      }
    }
  }, [noteId, isOpen, user])

  const handleEdit = () => {
    setIsEditing(true)
  }

  const handleCancelEdit = () => {
    if (note) {
      setEditTitle(note.title)
      setEditContent(note.content || '')
    }
    setIsEditing(false)
  }

  const handleSave = async () => {
    if (!note || !editTitle.trim() || !user) return

    setIsSaving(true)
    try {
      const updatedNote = await updateNote(note.id, {
        title: editTitle.trim(),
        content: editContent
      }, user.id)

      if (updatedNote) {
        setNote(updatedNote)
        setIsEditing(false)
        onNoteUpdated?.(updatedNote)
      }
    } catch (error) {
      console.error('Error updating note:', error)
    } finally {
      setIsSaving(false)
    }
  }

  const handleDelete = async () => {
    if (!note || !user) return

    const confirmed = window.confirm(`Are you sure you want to delete "${note.title}"? This action cannot be undone.`)
    if (!confirmed) return

    setIsDeleting(true)
    try {
      const success = await deleteNote(note.id, user.id)
      if (success) {
        onNoteDeleted?.(note.id)
        onClose()
      }
    } catch (error) {
      console.error('Error deleting note:', error)
    } finally {
      setIsDeleting(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape' && isEditing) {
      handleCancelEdit()
    } else if (e.key === 'Escape' && !isEditing) {
      onClose()
    } else if ((e.ctrlKey || e.metaKey) && e.key === 'Enter' && isEditing) {
      e.preventDefault()
      handleSave()
    }
  }

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr)
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit'
    })
  }

  if (!note) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-hidden flex flex-col">
          <DialogHeader>
            <DialogTitle>Note Not Found</DialogTitle>
            <DialogDescription>This note could not be found. It may have been deleted.</DialogDescription>
          </DialogHeader>
          <div className="flex-1 py-4">
            <p className="text-muted-foreground">This note could not be found. It may have been deleted.</p>
          </div>
          <div className="flex justify-end">
            <Button variant="outline" onClick={onClose}>
              Close
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    )
  }

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent
        className="max-w-4xl max-h-[85vh] overflow-hidden flex flex-col"
        onKeyDown={handleKeyDown}
      >
        <DialogHeader className="flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex-1">
              {isEditing ? (
                <Input
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  placeholder="Note title..."
                  className="text-lg font-semibold border-0 px-0 shadow-none focus-visible:ring-0"
                  autoFocus
                />
              ) : (
                <DialogTitle className="text-lg font-semibold">{note.title}</DialogTitle>
              )}
            </div>
            <div className="flex items-center gap-2 ml-4">
              {isEditing ? (
                <>
                  <Button
                    size="sm"
                    onClick={handleSave}
                    disabled={isSaving || !editTitle.trim()}
                    className="flex items-center gap-1"
                  >
                    <Save className="h-4 w-4" />
                    {isSaving ? 'Saving...' : 'Save'}
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={handleCancelEdit}
                    disabled={isSaving}
                  >
                    <X className="h-4 w-4" />
                    Cancel
                  </Button>
                </>
              ) : (
                <>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={handleEdit}
                    className="flex items-center gap-1"
                  >
                    <Edit className="h-4 w-4" />
                    Edit
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={handleDelete}
                    disabled={isDeleting}
                    className="flex items-center gap-1 text-destructive hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" />
                    {isDeleting ? 'Deleting...' : 'Delete'}
                  </Button>
                </>
              )}
            </div>
          </div>
          <DialogDescription className="flex items-center gap-2 text-sm text-muted-foreground mt-2">
            <Calendar className="h-3 w-3" />
            <span>Created: {formatDate(note.createdAt)}</span>
            {note.updatedAt && note.updatedAt !== note.createdAt && (
              <span>• Updated: {formatDate(note.updatedAt)}</span>
            )}
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto py-4">
          {isEditing ? (
            <SimpleRichEditor
              value={editContent}
              placeholder="Write your note content here..."
              onChange={setEditContent}
              autoFocus={false}
            />
          ) : (
            <div className="prose prose-sm max-w-none">
              {note.content ? (
                <div
                  className="text-base leading-relaxed"
                  dangerouslySetInnerHTML={{ __html: note.content }}
                />
              ) : (
                <p className="text-muted-foreground italic">This note has no content.</p>
              )}
            </div>
          )}
        </div>

        {!isEditing && (
          <div className="flex justify-between items-center pt-4 border-t flex-shrink-0">
            <div className="text-xs text-muted-foreground">
              Press <kbd className="px-1 py-0.5 bg-muted rounded">Esc</kbd> to close
            </div>
            <Button variant="outline" onClick={onClose}>
              Close
            </Button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  )
}

'use client'

/**
 * Ontology Analysis Button Component
 * Story 2.4.4: Incremental AI Ontology Analysis (Updated)
 *
 * Now calls the incremental analysis endpoint and shows last run info.
 */

import { useState, useEffect } from 'react'
import { Button } from '@/components/ui/button'
import { Sparkles, Loader2, Clock } from 'lucide-react'
import { toast } from 'sonner'
import { useAuth } from '@/contexts/AuthContext'

interface OntologyAnalysisButtonProps {
  onComplete?: () => void
}

export function OntologyAnalysisButton({
  onComplete
}: OntologyAnalysisButtonProps) {
  const { user } = useAuth()
  const [isAnalyzing, setIsAnalyzing] = useState(false)
  const [lastRunInfo, setLastRunInfo] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  // Load last run info on mount
  useEffect(() => {
    if (user) {
      loadLastRunInfo()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user])

  const loadLastRunInfo = async () => {
    if (!user) return

    try {
      // Fetch analysis state from safe API endpoint
      const response = await fetch('/api/ontology/analysis-state')

      if (!response.ok) {
        throw new Error('Failed to fetch analysis state')
      }

      const { state } = await response.json()

      if (state?.lastAnalyzedAt) {
        const lastRun = new Date(state.lastAnalyzedAt)
        const now = new Date()
        const diffMs = now.getTime() - lastRun.getTime()
        const diffMins = Math.floor(diffMs / 60000)
        const diffHours = Math.floor(diffMins / 60)
        const diffDays = Math.floor(diffHours / 24)

        let timeAgo = ''
        if (diffDays > 0) {
          timeAgo = `${diffDays} day${diffDays > 1 ? 's' : ''} ago`
        } else if (diffHours > 0) {
          timeAgo = `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`
        } else if (diffMins > 0) {
          timeAgo = `${diffMins} min${diffMins > 1 ? 's' : ''} ago`
        } else {
          timeAgo = 'just now'
        }

        setLastRunInfo(timeAgo)
      }
    } catch (error) {
      console.error('Failed to load last run info:', error)
    } finally {
      setIsLoading(false)
    }
  }

  const handleAnalyze = async () => {
    if (!user) {
      toast.error('Please sign in to analyze your ontology')
      return
    }

    setIsAnalyzing(true)

    try {
      // Call incremental analysis endpoint (same pipeline as scheduled runs)
      // Note: userId is derived from session on server for security
      const response = await fetch('/api/ontology/incremental-analysis', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          triggeredBy: 'manual'
        })
      })

      if (!response.ok) {
        const error = await response.json()
        throw new Error(error.details || error.error || 'Analysis failed')
      }

      const result = await response.json()

      if (!result.success) {
        throw new Error(result.error || 'Analysis failed')
      }

      // Check if skipped (no new notes)
      if (result.skipped) {
        toast.info('No new notes to analyze', {
          description: 'Your ontology is already up to date!'
        })
        setIsAnalyzing(false)
        return
      }

      // Show success message
      const { extraction, noteCount } = result
      const totalNew =
        (extraction?.newValues || 0) +
        (extraction?.newBeliefs || 0) +
        (extraction?.newAims || 0)

      toast.success('Ontology updated!', {
        description: `Analyzed ${noteCount} note${noteCount > 1 ? 's' : ''}. ${
          totalNew > 0 ? `Found ${totalNew} new insight${totalNew > 1 ? 's' : ''}` : 'Refreshed existing items'
        }`
      })

      // Refresh last run info
      await loadLastRunInfo()

      // Trigger refresh
      onComplete?.()
    } catch (error) {
      console.error('Analysis failed:', error)
      toast.error('Analysis failed', {
        description:
          error instanceof Error ? error.message : 'Please try again'
      })
    } finally {
      setIsAnalyzing(false)
    }
  }

  return (
    <div className="flex flex-col gap-2">
      <Button
        onClick={handleAnalyze}
        disabled={isAnalyzing}
        className="gap-2"
        size="lg"
      >
        {isAnalyzing ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" />
            Analyzing...
          </>
        ) : (
          <>
            <Sparkles className="h-4 w-4" />
            Analyze My Notes
          </>
        )}
      </Button>

      {!isLoading && lastRunInfo && (
        <div className="flex items-center gap-1.5 text-xs text-muted-foreground justify-center">
          <Clock className="h-3 w-3" />
          <span>Last updated {lastRunInfo}</span>
        </div>
      )}
    </div>
  )
}

'use client'

import Link from 'next/link'
import { Note } from '@/types/note'

interface OntologyCardViewerProps {
  note: Note
}

interface OntologyItem {
  name: string
  confidence: 'high' | 'medium' | 'low'
  excerpts: Array<{
    noteId: string
    noteTitle: string
    excerpt: string
  }>
}

export function OntologyCardViewer({ note }: OntologyCardViewerProps) {
  const items = (note.metadata?.items as OntologyItem[]) || []

  if (items.length === 0) {
    return (
      <div className="text-muted-foreground text-center py-12">
        <p className="text-lg font-medium mb-2">Empty</p>
        <p className="text-sm">
          Click &ldquo;Analyze My Notes&rdquo; on the Notes page to populate this card with AI-extracted insights.
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-8">
      {items.map((item, itemIndex) => (
        <div key={itemIndex} className="space-y-3">
          <h3 className="text-xl font-semibold text-foreground">
            {item.name}
          </h3>
          <ul className="space-y-4 pl-1">
            {item.excerpts.map((excerpt, excerptIndex) => (
              <li key={excerptIndex} className="text-sm leading-relaxed">
                <span className="text-muted-foreground italic">
                  &ldquo;{excerpt.excerpt}&rdquo;
                </span>
                {' '}
                <Link
                  href={`/notes/${excerpt.noteId}`}
                  className="text-primary hover:underline font-medium transition-colors"
                >
                  {excerpt.noteTitle}
                </Link>
              </li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  )
}

'use client'

import { Note, getNoteDisplayTitle } from '@/types/note'
import { Card, CardContent } from '@/components/ui/card'
import Link from 'next/link'

interface PinnedNoteCardProps {
  note: Note
}

export function PinnedNoteCard({ note }: PinnedNoteCardProps) {
  const MAX_PREVIEW_ITEMS = 5

  const renderPreview = () => {
    // Check if this is an ontology card with metadata.items
    const items = (note.metadata?.items as Array<{ name: string }>) || []
    if (items.length > 0) {
      const displayItems = items.slice(0, MAX_PREVIEW_ITEMS)
      const remaining = items.length - displayItems.length

      return (
        <div className="space-y-1.5">
          {displayItems.map((item, idx) => (
            <div key={idx} className="text-sm text-muted-foreground truncate">
              • {item.name}
            </div>
          ))}
          {remaining > 0 && (
            <div className="text-sm text-muted-foreground/70 italic">
              ... and {remaining} more
            </div>
          )}
        </div>
      )
    }

    // For aims notes with JSON content, parse and count
    const noteType = 'type' in note ? (note as { type: string }).type : note.noteType
    if (noteType === 'aims' || noteType === 'ontology-aim') {
      try {
        const parsed = JSON.parse(note.content)
        const todoLength = (parsed.todos || '').length
        const goalLength = (parsed.goals || '').length
        if (todoLength + goalLength > 0) {
          return (
            <p className="text-sm text-muted-foreground">
              {todoLength + goalLength} characters
            </p>
          )
        }
      } catch {
        // Fall through to content check
      }
    }

    // Default: check content length
    return (
      <p className="text-sm text-muted-foreground">
        {note.content.length > 0 ? `${note.content.length} characters` : 'Empty'}
      </p>
    )
  }

  return (
    <Link href={`/notes/${note.id}`}>
      <Card className="hover:bg-accent/50 transition-colors cursor-pointer h-full">
        <CardContent className="p-6">
          <h3 className="text-lg font-semibold mb-2">{getNoteDisplayTitle(note)}</h3>
          {renderPreview()}
        </CardContent>
      </Card>
    </Link>
  )
}

'use client'

import { Note } from '@/types/note'
import { Card, CardContent } from '@/components/ui/card'
import Link from 'next/link'

interface RegularNoteCardProps {
  note: Note
}

export function RegularNoteCard({ note }: RegularNoteCardProps) {
  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr)
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    })
  }

  const getPreview = (content: string, maxLength: number = 100) => {
    // Strip HTML tags for preview
    const text = content.replace(/<[^>]*>/g, '')
    if (text.length <= maxLength) return text
    return text.substring(0, maxLength) + '...'
  }

  const getOntologyPreview = () => {
    const items = (note.metadata?.items as Array<{ name: string }>) || []
    if (items.length === 0) return 'Empty'
    const names = items.map(item => item.name).join(', ')
    return names.length > 100 ? names.substring(0, 100) + '...' : names
  }

  const isOntologyCard = note.noteType === 'ontology-value' ||
                         note.noteType === 'ontology-belief' ||
                         note.noteType === 'ontology-aim'

  return (
    <Link href={`/notes/${note.id}`} className="block mb-4">
      <Card className="hover:bg-accent/50 transition-colors cursor-pointer">
        <CardContent className="p-4">
          <div className="flex justify-between items-start gap-4">
            <div className="flex-1 min-w-0">
              <h4 className="font-medium mb-1 truncate">{note.title}</h4>
              <p className="text-sm text-muted-foreground line-clamp-2">
                {isOntologyCard
                  ? getOntologyPreview()
                  : note.content
                    ? getPreview(note.content)
                    : 'No content'}
              </p>
            </div>
            <time className="text-xs text-muted-foreground whitespace-nowrap">
              {formatDate(note.createdAt)}
            </time>
          </div>
        </CardContent>
      </Card>
    </Link>
  )
}

'use client'

import { useRef, useEffect } from 'react'
import { Note, getNoteDisplayTitle } from '@/types/note'
import { Card, CardContent } from '@/components/ui/card'
import { ChevronDown, ChevronUp } from 'lucide-react'

interface ExpandableOntologyRowProps {
  note: Note
  isExpanded: boolean
  onToggle: () => void
}

export function ExpandableOntologyRow({ note, isExpanded, onToggle }: ExpandableOntologyRowProps) {
  const category = note.noteType.replace('ontology-', '')
  const contentId = `ontology-${category}-content`
  const buttonRef = useRef<HTMLButtonElement>(null)
  const liveRegionRef = useRef<HTMLDivElement>(null)
  const title = getNoteDisplayTitle(note)

  // Announce expansion state changes to screen readers
  useEffect(() => {
    if (liveRegionRef.current) {
      liveRegionRef.current.textContent = isExpanded
        ? `${title} expanded`
        : `${title} collapsed`
    }
  }, [isExpanded, title])

  // Extract items from metadata
  const items = (note.metadata?.items as Array<{
    name: string
    excerpts: Array<{
      noteId: string
      noteTitle: string
      excerpt: string
    }>
  }>) || []

  return (
    <Card className="w-full">
      <button
        ref={buttonRef}
        onClick={onToggle}
        aria-expanded={isExpanded}
        aria-controls={contentId}
        className="w-full text-left transition-colors hover:bg-accent/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 rounded-t-lg"
      >
        <CardContent className="p-6">
          <div className="flex items-start justify-between gap-4">
            <div className="flex-1 min-w-0">
              <h2 className="text-lg font-semibold mb-3">{title}</h2>
              {items.length > 0 && (
                <ul className="space-y-1 text-sm text-muted-foreground">
                  {items.map((item) => (
                    <li key={item.name}>• {item.name}</li>
                  ))}
                </ul>
              )}
            </div>
            <div className="flex items-center gap-2 text-sm text-muted-foreground shrink-0">
              <span>{isExpanded ? 'Collapse' : 'Expand'}</span>
              {isExpanded ? (
                <ChevronUp className="h-5 w-5" aria-hidden="true" />
              ) : (
                <ChevronDown className="h-5 w-5" aria-hidden="true" />
              )}
            </div>
          </div>
        </CardContent>
      </button>

      {/* Screen reader live region for announcements */}
      <div
        ref={liveRegionRef}
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      />

      {isExpanded && (
        <div
          id={contentId}
          className="expanded-content"
          role="region"
          aria-labelledby={`${category}-heading`}
        >
          <CardContent className="px-6 pb-6 pt-0 space-y-6">
            {/* Auto-update notice */}
            <div className="rounded-md bg-amber-50 dark:bg-amber-950/20 border border-amber-200 dark:border-amber-900 p-4 text-sm text-amber-900 dark:text-amber-100">
              This note is automatically updated as you write in your journal.
            </div>

            {/* Concept sections with excerpts */}
            {items.map((item) => (
              <div key={item.name} className="space-y-3">
                <h3
                  id={`${category}-heading`}
                  className="text-base font-semibold"
                >
                  {item.name}
                </h3>
                <div className="space-y-2">
                  {item.excerpts.map((excerpt, idx) => (
                    <blockquote
                      key={idx}
                      className="border-l-4 border-muted pl-4 py-2 text-sm space-y-1"
                    >
                      <p className="text-foreground italic">&ldquo;{excerpt.excerpt}&rdquo;</p>
                      <cite className="text-xs text-muted-foreground not-italic">
                        {excerpt.noteTitle}
                      </cite>
                    </blockquote>
                  ))}
                </div>
              </div>
            ))}

            {items.length === 0 && (
              <p className="text-sm text-muted-foreground text-center py-8">
                No items yet. Click &ldquo;Analyze My Notes&rdquo; to extract your {title.toLowerCase()}.
              </p>
            )}
          </CardContent>
        </div>
      )}
    </Card>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useSearchParams } from 'next/navigation'
import { initializePinnedNotes, getPinnedNotes } from '@/lib/notes'
import { Note } from '@/types/note'
import { OntologyAnalysisButton } from '../notes/OntologyAnalysisButton'
import { ExpandableOntologyRow } from './ExpandableOntologyRow'
import { useAuth } from '@/contexts/AuthContext'

// Helper: SSR-safe localStorage access
function getStoredExpanded(): Set<string> {
  if (typeof window === 'undefined') return new Set()
  try {
    const stored = localStorage.getItem('ontology-expanded')
    return stored ? new Set(JSON.parse(stored)) : new Set()
  } catch {
    return new Set()
  }
}

export function OntologyPage() {
  const { user } = useAuth()
  const searchParams = useSearchParams()
  const [pinnedNotes, setPinnedNotes] = useState<Note[]>([])
  const [expandedCards, setExpandedCards] = useState<Set<string>>(new Set())
  const [isHydrated, setIsHydrated] = useState(false)

  const loadNotes = async () => {
    if (!user) return
    setPinnedNotes(await getPinnedNotes(user.id))
  }

  // Hydrate expansion state from URL params and localStorage
  // CRITICAL: URL params ALWAYS override localStorage
  useEffect(() => {
    const urlParam = searchParams.get('expanded')
    const urlExpanded = urlParam?.split(',').filter(Boolean) || []

    if (urlExpanded.length > 0) {
      // URL params present: use ONLY URL params (ignore localStorage)
      setExpandedCards(new Set(urlExpanded))
    } else {
      // No URL params: restore from localStorage
      const stored = getStoredExpanded()
      setExpandedCards(stored)
    }

    setIsHydrated(true)
  }, [searchParams])

  // Persist expansion state to localStorage
  useEffect(() => {
    if (!isHydrated) return // Skip initial render to avoid race
    if (typeof window !== 'undefined') {
      localStorage.setItem('ontology-expanded', JSON.stringify([...expandedCards]))
    }
  }, [expandedCards, isHydrated])

  useEffect(() => {
    if (!user) {
      // Clear notes when user signs out to prevent data leakage
      setPinnedNotes([])
      return
    }

    // Initialize pinned notes if they don't exist, then load all notes
    (async () => {
      await initializePinnedNotes(user.id)
      await loadNotes()
    })()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user])

  const toggleCard = (category: string) => {
    setExpandedCards((prev) => {
      const next = new Set(prev)
      if (next.has(category)) {
        next.delete(category)
      } else {
        next.add(category)
      }
      return next
    })
  }

  // Sort notes to ensure consistent order: Values, Beliefs, Goals
  const sortedNotes = [...pinnedNotes].sort((a, b) => {
    const order = { 'ontology-value': 0, 'ontology-belief': 1, 'ontology-aim': 2 }
    return (order[a.noteType as keyof typeof order] || 999) - (order[b.noteType as keyof typeof order] || 999)
  })

  return (
    <div className="max-w-5xl mx-auto p-6 space-y-8">
      {/* Ontology Cards Section */}
      <section>
        <div className="flex items-center justify-end mb-4">
          <OntologyAnalysisButton onComplete={loadNotes} />
        </div>

        {/* Expandable rows stacked vertically */}
        <div className="space-y-4">
          {sortedNotes.map((note) => {
            const category = note.noteType.replace('ontology-', '')
            return (
              <ExpandableOntologyRow
                key={note.id}
                note={note}
                isExpanded={expandedCards.has(category)}
                onToggle={() => toggleCard(category)}
              />
            )
          })}
        </div>
      </section>
    </div>
  )
}

'use client'

import { ThemeProvider as NextThemesProvider } from 'next-themes'
import type { ReactNode } from 'react'

interface ThemeProviderProps {
  children: ReactNode
}

export function ThemeProvider({ children }: ThemeProviderProps) {
  return (
    <NextThemesProvider
      attribute="class"
      defaultTheme="system"
      enableSystem
      storageKey="signum-theme"
      disableTransitionOnChange
    >
      {children}
    </NextThemesProvider>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useTheme } from 'next-themes'
import { Moon, Sun } from 'lucide-react'
import { cn } from '@/lib/utils'

const TOGGLE_CLASSES =
  'peer focus-visible:ring-ring focus-visible:ring-offset-background inline-flex h-6 w-11 shrink-0 cursor-pointer items-center rounded-full border-2 border-transparent transition-colors focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:outline-hidden disabled:cursor-not-allowed disabled:opacity-50'

const THUMB_CLASSES =
  'pointer-events-none flex size-5 items-center justify-center rounded-full bg-background shadow-lg ring-0 transition-transform data-[state=checked]:translate-x-5 data-[state=unchecked]:translate-x-0'

const ICON_SIZE = 'size-3'

export function ThemeToggle() {
  const { setTheme, resolvedTheme } = useTheme()
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
  }, [])

  if (!mounted) {
    return <div className="inline-flex h-6 w-11 shrink-0 items-center rounded-full bg-muted/60" aria-hidden="true" />
  }

  const isDark = resolvedTheme === 'dark'
  const iconClass = cn(ICON_SIZE, isDark ? 'text-foreground' : 'text-muted-foreground')

  const handleToggle = () => {
    setTheme(isDark ? 'light' : 'dark')
  }

  return (
    <button
      type="button"
      role="switch"
      aria-checked={isDark}
      data-state={isDark ? 'checked' : 'unchecked'}
      onClick={handleToggle}
      className={cn(
        TOGGLE_CLASSES,
        isDark ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'
      )}
    >
      <span data-state={isDark ? 'checked' : 'unchecked'} className={THUMB_CLASSES}>
        {isDark ? <Moon className={iconClass} aria-hidden="true" /> : <Sun className={iconClass} aria-hidden="true" />}
      </span>
      <span className="sr-only">Toggle theme</span>
    </button>
  )
}

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2 has-[>svg]:px-3",
        sm: "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        lg: "h-10 rounded-md px-6 has-[>svg]:px-4",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

function Button({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const Comp = asChild ? Slot : "button"

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  )
}

export { Button, buttonVariants }

