/**
 * Notes CRUD operations using Supabase.
 * Story 2.4.1: Authenticated data access with user-specific isolation.
 *
 * All functions require authenticated user ID from Supabase session.
 */

import {
  Note,
  CreateNoteRequest,
  UpdateNoteRequest
} from '@/types/note'
import * as supabaseNotes from '@/lib/supabase/notes'

/**
 * Get all notes for authenticated user (calls Supabase)
 */
export async function getNotes(userId: string): Promise<Note[]> {
  try {
    const [journal, regular, ontology] = await Promise.all([
      supabaseNotes.getJournalEntries(userId),
      supabaseNotes.getRegularNotes(userId),
      supabaseNotes.getOntologyNotes(userId)
    ])
    return [...journal, ...regular, ...ontology]
  } catch (error) {
    console.error('Error loading notes from Supabase:', error)
    return []
  }
}

/**
 * Create a new note for authenticated user (calls Supabase)
 */
export async function createNote(request: CreateNoteRequest, userId: string): Promise<Note> {
  return await supabaseNotes.createNote(request, userId)
}

/**
 * Update an existing note for authenticated user (calls Supabase)
 */
export async function updateNote(id: string, updates: Partial<Note>, userId: string): Promise<Note | null> {
  try {
    const updateRequest: UpdateNoteRequest = {
      id,
      title: updates.title,
      content: updates.content,
      isPinned: updates.isPinned,
      metadata: updates.metadata
    }
    return await supabaseNotes.updateNote(updateRequest, userId)
  } catch (error) {
    console.error('Error updating note:', error)
    return null
  }
}

/**
 * Delete a note for authenticated user (calls Supabase)
 */
export async function deleteNote(id: string, userId: string): Promise<boolean> {
  try {
    await supabaseNotes.deleteNote(id, userId)
    return true
  } catch (error) {
    console.error('Error deleting note:', error)
    return false
  }
}

/**
 * Get a single note by ID for authenticated user (calls Supabase)
 */
export async function getNoteById(id: string, userId: string): Promise<Note | null> {
  try {
    return await supabaseNotes.getNoteById(id, userId)
  } catch (error) {
    console.error('Error fetching note:', error)
    return null
  }
}

/**
 * Initialize pinned ontology notes (Values, Beliefs, Aims) for authenticated user
 * Creates any missing ontology notes individually to recover from partial data
 */
export async function initializePinnedNotes(userId: string): Promise<void> {
  try {
    // Check which ontology notes exist
    const existingOntology = await supabaseNotes.getOntologyNotes(userId)
    const existingTypes = new Set(existingOntology.map(note => note.noteType))

    // Define required ontology notes
    const requiredNotes: Array<{
      type: 'ontology-value' | 'ontology-belief' | 'ontology-aim'
      title: string
      content: string
    }> = [
      { type: 'ontology-value', title: 'Values', content: '' },
      { type: 'ontology-belief', title: 'Beliefs', content: '' },
      { type: 'ontology-aim', title: 'Goals', content: JSON.stringify({ todos: '', goals: '' }) }
    ]

    // Create missing notes individually
    for (const noteConfig of requiredNotes) {
      if (!existingTypes.has(noteConfig.type)) {
        await createNote({
          title: noteConfig.title,
          content: noteConfig.content,
          noteType: noteConfig.type,
          isPinned: true,
          metadata: {}
        }, userId)
      }
    }
  } catch (error) {
    console.error('Error initializing pinned notes:', error)
  }
}

/**
 * Get pinned ontology notes (Values, Beliefs, Aims) for authenticated user
 */
export async function getPinnedNotes(userId: string): Promise<Note[]> {
  try {
    return await supabaseNotes.getOntologyNotes(userId)
  } catch (error) {
    console.error('Error fetching pinned notes:', error)
    return []
  }
}

/**
 * Get regular notes (excluding pinned ontology notes) for authenticated user
 */
export async function getRegularNotes(userId: string): Promise<Note[]> {
  try {
    return await supabaseNotes.getRegularNotes(userId)
  } catch (error) {
    console.error('Error fetching regular notes:', error)
    return []
  }
}

/**
 * Store ontology items (for AI extraction - Story 2.4.2) for authenticated user
 * Handles deduplication by title (case-insensitive)
 */
export async function storeOntologyItems(
  items: Omit<Note, 'id' | 'createdAt' | 'updatedAt'>[],
  noteType: 'ontology-value' | 'ontology-belief' | 'ontology-aim',
  userId: string
): Promise<Note[]> {
  try {
    const existingNotes = await supabaseNotes.getOntologyNotes(userId)

    // Create map of existing ontology notes by lowercase title
    const existingMap = new Map<string, Note>()
    existingNotes
      .filter(note => note.noteType === noteType)
      .forEach(note => {
        existingMap.set(note.title.toLowerCase(), note)
      })

    const createdNotes: Note[] = []
    const updatedNotes: Note[] = []

    // Process each item
    for (const item of items) {
      const lowercaseTitle = item.title.toLowerCase()
      const existing = existingMap.get(lowercaseTitle)

      if (existing) {
        // Update existing note
        const updateRequest: UpdateNoteRequest = {
          id: existing.id,
          content: item.content,
          metadata: {
            ...existing.metadata,
            ...item.metadata
          }
        }
        const updated = await supabaseNotes.updateNote(updateRequest, userId)
        updatedNotes.push(updated)
      } else {
        // Create new note
        const createRequest: CreateNoteRequest = {
          title: item.title,
          content: item.content,
          noteType: item.noteType,
          isPinned: item.isPinned,
          metadata: item.metadata
        }
        const created = await supabaseNotes.createNote(createRequest, userId)
        createdNotes.push(created)
      }
    }

    return [...createdNotes, ...updatedNotes]
  } catch (error) {
    console.error('Error storing ontology items:', error)
    return []
  }
}

/**
 * Deduplication logic for ontology items
 * Story 2.4: AI Personal Ontology Extraction
 */

import { Note } from '@/types/note'
import { OntologyItem } from '@/utils/ontologyPrompts'

/**
 * Deduplicate ontology items by title (case-insensitive)
 * Merges source note IDs and keeps highest confidence
 */
export function deduplicateOntologyItems(
  newItems: OntologyItem[],
  existingNotes: Note[],
  noteType: 'ontology-value' | 'ontology-belief' | 'ontology-aim'
): OntologyItem[] {
  // Filter existing notes by type
  const existingOntologyNotes = existingNotes.filter(
    (note) => note.noteType === noteType
  )

  // Create map of existing titles (lowercase for case-insensitive matching)
  const existingTitlesMap = new Map<string, Note>()
  existingOntologyNotes.forEach((note) => {
    existingTitlesMap.set(note.title.toLowerCase(), note)
  })

  // Deduplicate new items
  const deduplicatedItems: OntologyItem[] = []
  const seenTitles = new Set<string>()

  for (const item of newItems) {
    const lowercaseTitle = item.text.toLowerCase()

    // Check if exists in localStorage
    const existingNote = existingTitlesMap.get(lowercaseTitle)
    if (existingNote) {
      // Merge excerpts (combine with new item's excerpts)
      const existingExcerpts = (existingNote.metadata?.items?.[0]?.excerpts || [])
      const mergedExcerpts = [
        ...existingExcerpts,
        ...item.sourceExcerpts
      ]

      // Keep higher confidence
      const existingConfidence = existingNote.metadata?.confidence || 'low'
      const confidenceRank = { high: 3, medium: 2, low: 1 }
      const newConfidence =
        confidenceRank[item.confidence] >
        confidenceRank[existingConfidence as keyof typeof confidenceRank]
          ? item.confidence
          : existingConfidence

      // Create updated item
      deduplicatedItems.push({
        text: existingNote.title, // Keep original casing
        confidence: newConfidence as 'high' | 'medium' | 'low',
        sourceExcerpts: mergedExcerpts
      })

      continue
    }

    // Check if duplicate in new items
    if (seenTitles.has(lowercaseTitle)) {
      // Find existing item in deduplicatedItems
      const existingIndex = deduplicatedItems.findIndex(
        (di) => di.text.toLowerCase() === lowercaseTitle
      )

      if (existingIndex !== -1) {
        const existing = deduplicatedItems[existingIndex]
        // Merge excerpts
        existing.sourceExcerpts = [
          ...existing.sourceExcerpts,
          ...item.sourceExcerpts
        ]
      }

      continue
    }

    // New unique item
    seenTitles.add(lowercaseTitle)
    deduplicatedItems.push(item)
  }

  return deduplicatedItems
}

/**
 * Convert ontology items to Note objects for storage
 */
export function ontologyItemsToNotes(
  items: OntologyItem[],
  noteType: 'ontology-value' | 'ontology-belief' | 'ontology-aim'
): Omit<Note, 'id' | 'createdAt' | 'updatedAt'>[] {
  return items.map((item) => ({
    userId: '', // Will be set by caller
    title: item.text,
    content: '', // Keep empty - data is in metadata
    noteType,
    isPinned: true, // Ontology items are always pinned
    metadata: {
      confidence: item.confidence,
      items: [{
        name: item.text,
        confidence: item.confidence,
        excerpts: item.sourceExcerpts
      }]
    }
  }))
}

/**
 * Incremental Ontology Extraction Service
 * Story 2.4.4: Incremental AI Ontology Analysis
 *
 * Handles extracting ontology items from new/updated notes
 * and merging with existing ontology.
 */

import OpenAI from 'openai'
import { Note, NoteMetadata } from '@/types/note'
import {
  ExtractionResult,
  parseExtractionResult
} from '@/utils/ontologyPrompts'
import { mergeOntologyItems } from './merge'
import { supabaseAdmin } from '@/lib/supabase-admin'

const openai = process.env.OPENAI_API_KEY
  ? new OpenAI({
      apiKey: process.env.OPENAI_API_KEY
    })
  : null

export interface IncrementalExtractionResult {
  newValues: number
  newBeliefs: number
  newAims: number
  mergedValues: number
  mergedBeliefs: number
  mergedAims: number
}

/**
 * Build incremental extraction prompt
 * Includes summary of existing ontology to avoid duplicates
 */
function buildIncrementalPrompt(
  newNotes: Note[],
  existingOntology: {
    values: string[]
    beliefs: string[]
    aims: string[]
  }
): string {
  const notesText = newNotes
    .map((note, index) => {
      return `[Note ${index + 1} - ID: ${note.id}]
Title: ${note.title}
Content: ${note.content}
---`
    })
    .join('\n\n')

  const existingValuesText =
    existingOntology.values.length > 0
      ? `\nExisting Values:\n${existingOntology.values.map((v) => `- ${v}`).join('\n')}`
      : ''

  const existingBeliefsText =
    existingOntology.beliefs.length > 0
      ? `\nExisting Beliefs:\n${existingOntology.beliefs.map((b) => `- ${b}`).join('\n')}`
      : ''

  const existingAimsText =
    existingOntology.aims.length > 0
      ? `\nExisting Aims:\n${existingOntology.aims.map((a) => `- ${a}`).join('\n')}`
      : ''

  return `You are an expert at analyzing personal journal entries and notes to extract core philosophical concepts.

Your task is to identify NEW or UPDATED items from the recent notes that are not already in the existing ontology:

1. **Values**: Guiding principles and what matters most (e.g., "Compassion", "Integrity", "Growth")
2. **Beliefs**: Deeply held truths and worldviews (e.g., "People have inherent wisdom", "Meaning comes through struggle")
3. **Aims**: Personal goals and aspirations (e.g., "Build authentic relationships", "Balance ambition with presence")

EXISTING ONTOLOGY (avoid duplicates):${existingValuesText}${existingBeliefsText}${existingAimsText}

IMPORTANT GUIDELINES:
- Extract only HIGH-CONFIDENCE items that appear multiple times or are stated explicitly
- AVOID duplicating items from the existing ontology above
- If a new note provides additional evidence for an existing item, include it with the existing item's title
- Keep extracted text SHORT and MEMORABLE (2-5 words ideally)
- For each value/belief/aim, provide up to 5 most representative excerpts
- Each excerpt should be 1-2 sentences of actual text from the notes
- Include the exact quote that demonstrates this concept
- Provide noteId and noteTitle for each excerpt
- Look for recurring themes across multiple notes
- Distinguish between values (principles), beliefs (truths), and aims (goals)

NEW NOTES TO ANALYZE:

${notesText}

RESPONSE FORMAT: Prefer returning raw JSON without markdown code blocks. If you include markdown formatting, ensure the content is still valid JSON.

Return your analysis as JSON in this exact format:
{
  "values": [
    {
      "text": "Compassion",
      "confidence": "high",
      "sourceExcerpts": [
        {
          "noteId": "note-id-1",
          "noteTitle": "Journal Entry - Oct 15",
          "excerpt": "Sometimes the most valuable conversations are the ones where you just witness each other's experience without trying to fix anything."
        }
      ]
    }
  ],
  "beliefs": [
    {
      "text": "Meaning over happiness",
      "confidence": "high",
      "sourceExcerpts": [
        {
          "noteId": "note-id-3",
          "noteTitle": "Journal Entry - Oct 12",
          "excerpt": "I'm realizing that constantly chasing happiness might miss the point."
        }
      ]
    }
  ],
  "aims": [
    {
      "text": "Balance ambition with presence",
      "confidence": "high",
      "sourceExcerpts": [
        {
          "noteId": "note-id-1",
          "noteTitle": "Work Reflection",
          "excerpt": "I keep pushing for the next milestone, but I'm missing what's happening right now."
        }
      ]
    }
  ]
}

Only include items with "high" confidence. Return empty arrays if no high-confidence items found.`
}

/**
 * Get existing ontology items for a user
 */
async function getExistingOntology(userId: string): Promise<{
  values: Note[]
  beliefs: Note[]
  aims: Note[]
  valueTexts: string[]
  beliefTexts: string[]
  aimTexts: string[]
}> {
  // SECURITY FIX: Issue #4 - Use admin client to bypass RLS in server context
  const { data: ontologyNotes, error } = await supabaseAdmin
    .from('notes')
    .select('*')
    .eq('user_id', userId)
    .in('note_type', ['ontology-value', 'ontology-belief', 'ontology-aim'])

  if (error) {
    console.error('Failed to get existing ontology:', error)
    throw error
  }

  // Convert snake_case to camelCase for TypeScript Note type
  const convertToNote = (row: {
    id: string
    user_id: string
    title: string
    content: string
    note_type: string
    is_pinned: boolean
    metadata: NoteMetadata
    created_at: string
    updated_at: string
  }): Note => ({
    id: row.id,
    userId: row.user_id,
    title: row.title,
    content: row.content,
    noteType: row.note_type as Note['noteType'],
    isPinned: row.is_pinned,
    metadata: row.metadata,
    createdAt: row.created_at,
    updatedAt: row.updated_at
  })

  const values = ontologyNotes?.filter((n) => n.note_type === 'ontology-value').map(convertToNote) || []
  const beliefs = ontologyNotes?.filter((n) => n.note_type === 'ontology-belief').map(convertToNote) || []
  const aims = ontologyNotes?.filter((n) => n.note_type === 'ontology-aim').map(convertToNote) || []

  // Extract text summaries from metadata
  const extractTexts = (notes: Note[]) => {
    const texts: string[] = []
    notes.forEach((note) => {
      if (note.metadata?.items) {
        note.metadata.items.forEach((item) => {
          if (item.name) texts.push(item.name)
        })
      }
    })
    return texts
  }

  return {
    values,
    beliefs,
    aims,
    valueTexts: extractTexts(values),
    beliefTexts: extractTexts(beliefs),
    aimTexts: extractTexts(aims)
  }
}

/**
 * Run incremental extraction on new notes
 */
export async function runIncrementalExtraction(
  userId: string,
  newNotes: Note[]
): Promise<IncrementalExtractionResult> {
  if (!openai) {
    throw new Error('OpenAI API key not configured')
  }

  // 1. Get existing ontology
  const existing = await getExistingOntology(userId)

  // 2. Build incremental prompt
  const prompt = buildIncrementalPrompt(newNotes, {
    values: existing.valueTexts,
    beliefs: existing.beliefTexts,
    aims: existing.aimTexts
  })

  // 3. Call OpenAI GPT-5-mini
  const response = await openai.responses.create({
    model: 'gpt-5-mini',
    input: prompt,
    reasoning: {
      effort: 'medium'
    }
  })

  // 4. Extract response text (handle gpt-5-mini quirks)
  let responseText = response.output_text

  if (!responseText && response.output) {
    const textChunks: string[] = []
    for (const item of response.output) {
      if (item.type === 'message' && item.content) {
        for (const contentItem of item.content) {
          if (contentItem.type === 'output_text' && 'text' in contentItem) {
            textChunks.push(contentItem.text)
          }
        }
      }
    }
    responseText = textChunks.join('')
  }

  if (!responseText) {
    throw new Error('No response from OpenAI')
  }

  // 5. Parse extraction result
  const extraction: ExtractionResult = parseExtractionResult(responseText)

  // 6. Merge with existing ontology
  const mergeResults = await mergeOntologyItems(
    userId,
    extraction,
    existing
  )

  return {
    newValues: mergeResults.newValues,
    newBeliefs: mergeResults.newBeliefs,
    newAims: mergeResults.newAims,
    mergedValues: mergeResults.mergedValues,
    mergedBeliefs: mergeResults.mergedBeliefs,
    mergedAims: mergeResults.mergedAims
  }
}

/**
 * Ontology Merge & Persistence Logic
 * Story 2.4.4: Incremental AI Ontology Analysis
 *
 * Handles merging newly extracted ontology items with existing ones,
 * including deduplication, confidence reconciliation, and metadata aggregation.
 */

import { supabaseAdmin } from '@/lib/supabase-admin'
import { Note } from '@/types/note'
import { ExtractionResult, OntologyItem } from '@/utils/ontologyPrompts'

export interface MergeResult {
  newValues: number
  newBeliefs: number
  newAims: number
  mergedValues: number
  mergedBeliefs: number
  mergedAims: number
}

/**
 * Normalize text for matching (lowercase, trim, remove extra spaces)
 */
function normalizeText(text: string): string {
  return text.toLowerCase().trim().replace(/\s+/g, ' ')
}


/**
 * Reconcile confidence levels - returns higher confidence
 */
function reconcileConfidence(
  conf1: 'high' | 'medium' | 'low',
  conf2: 'high' | 'medium' | 'low'
): 'high' | 'medium' | 'low' {
  const ranking = { high: 3, medium: 2, low: 1 }
  return ranking[conf1] >= ranking[conf2] ? conf1 : conf2
}

/**
 * Merge source excerpts, removing duplicates
 */
function mergeSourceExcerpts(
  existingExcerpts: OntologyItem['sourceExcerpts'],
  newExcerpts: OntologyItem['sourceExcerpts']
): OntologyItem['sourceExcerpts'] {
  const merged = [...existingExcerpts]
  const existingKeys = new Set(
    existingExcerpts.map((e) => `${e.noteId}:${e.excerpt}`)
  )

  for (const newExcerpt of newExcerpts) {
    const key = `${newExcerpt.noteId}:${newExcerpt.excerpt}`
    if (!existingKeys.has(key)) {
      merged.push(newExcerpt)
    }
  }

  return merged
}

/**
 * Merge newly extracted ontology items with existing ontology
 */
export async function mergeOntologyItems(
  userId: string,
  extraction: ExtractionResult,
  existing: {
    values: Note[]
    beliefs: Note[]
    aims: Note[]
  }
): Promise<MergeResult> {
  let newValues = 0
  let newBeliefs = 0
  let newAims = 0
  let mergedValues = 0
  let mergedBeliefs = 0
  let mergedAims = 0

  // Helper to process each category
  async function processCategory(
    newItems: OntologyItem[],
    existingNotes: Note[],
    noteType: 'ontology-value' | 'ontology-belief' | 'ontology-aim'
  ): Promise<{ newCount: number; mergedCount: number }> {
    let newCount = 0
    let mergedCount = 0

    // Get the pinned ontology note for this category
    // SECURITY FIX: Filter by isPinned to avoid corrupting individual ontology cards
    const pinnedNote = existingNotes.find((n) => n.noteType === noteType && n.isPinned)

    if (!pinnedNote) {
      throw new Error(`Pinned ${noteType} note not found`)
    }

    // Get existing items from metadata
    const existingItems = (pinnedNote.metadata?.items || []) as Array<{
      name: string
      confidence: 'high' | 'medium' | 'low'
      excerpts: OntologyItem['sourceExcerpts']
    }>

    // Build map of existing items by normalized name
    const existingMap = new Map<string, typeof existingItems[0]>()
    existingItems.forEach((item) => {
      existingMap.set(normalizeText(item.name), item)
    })

    // Process new items
    const updatedItems = [...existingItems]

    for (const newItem of newItems) {
      const normalizedName = normalizeText(newItem.text)
      const existing = existingMap.get(normalizedName)

      if (existing) {
        // Merge with existing
        mergedCount++

        // Update confidence if new is higher
        const newConfidence = reconcileConfidence(
          existing.confidence,
          newItem.confidence
        )

        // Merge excerpts
        const mergedExcerpts = mergeSourceExcerpts(
          existing.excerpts,
          newItem.sourceExcerpts
        )

        // Update in array
        const index = updatedItems.findIndex(
          (item) => normalizeText(item.name) === normalizedName
        )
        if (index !== -1) {
          updatedItems[index] = {
            ...existing,
            confidence: newConfidence,
            excerpts: mergedExcerpts
          }
        }
      } else {
        // New item
        newCount++
        updatedItems.push({
          name: newItem.text,
          confidence: newItem.confidence,
          excerpts: newItem.sourceExcerpts
        })
      }
    }

    // Update the pinned note with merged items (SECURITY FIX: Issue #4)
    const { error } = await supabaseAdmin
      .from('notes')
      .update({
        metadata: {
          ...pinnedNote.metadata,
          items: updatedItems
        }
      })
      .eq('id', pinnedNote.id)
      .eq('user_id', userId)

    if (error) {
      console.error(`Failed to update ${noteType}:`, error)
      throw error
    }

    return { newCount, mergedCount }
  }

  // Process each category
  try {
    // Values
    const valuesResult = await processCategory(
      extraction.values,
      existing.values,
      'ontology-value'
    )
    newValues = valuesResult.newCount
    mergedValues = valuesResult.mergedCount

    // Beliefs
    const beliefsResult = await processCategory(
      extraction.beliefs,
      existing.beliefs,
      'ontology-belief'
    )
    newBeliefs = beliefsResult.newCount
    mergedBeliefs = beliefsResult.mergedCount

    // Aims
    const aimsResult = await processCategory(
      extraction.aims,
      existing.aims,
      'ontology-aim'
    )
    newAims = aimsResult.newCount
    mergedAims = aimsResult.mergedCount

    return {
      newValues,
      newBeliefs,
      newAims,
      mergedValues,
      mergedBeliefs,
      mergedAims
    }
  } catch (error) {
    console.error('Merge failed:', error)
    throw error
  }
}

/**
 * Deduplicate ontology items within a list (helper for initial extraction)
 */
export function deduplicateWithinList(items: OntologyItem[]): OntologyItem[] {
  const seen = new Map<string, OntologyItem>()

  for (const item of items) {
    const normalized = normalizeText(item.text)
    const existing = seen.get(normalized)

    if (existing) {
      // Merge with existing in list
      existing.confidence = reconcileConfidence(
        existing.confidence,
        item.confidence
      )
      existing.sourceExcerpts = mergeSourceExcerpts(
        existing.sourceExcerpts,
        item.sourceExcerpts
      )
    } else {
      seen.set(normalized, { ...item })
    }
  }

  return Array.from(seen.values())
}

/**
 * Ontology Analysis State Management
 * Story 2.4.4: Incremental AI Ontology Analysis
 *
 * Handles tracking when users' ontologies were last analyzed
 * and provides helpers for incremental analysis workflows.
 *
 * Uses admin client to bypass RLS for state management operations.
 */

import { supabaseAdmin } from '@/lib/supabase-admin'
import { Note } from '@/types/note'

// ============================================================================
// Types
// ============================================================================

export interface AnalysisState {
  userId: string
  lastAnalyzedAt: string | null
  lastRunSummary: AnalysisRunSummary
  createdAt: string
  updatedAt: string
}

export interface AnalysisRunSummary {
  triggeredBy?: 'manual' | 'scheduled'
  noteCount?: number
  runtime?: number // milliseconds
  tokenEstimate?: number
  status?: 'success' | 'failure' | 'skipped'
  error?: string
  extractedCounts?: {
    values: number
    beliefs: number
    aims: number
  }
  timestamp?: string
}

// ============================================================================
// State Management Functions
// ============================================================================

/**
 * Get analysis state for a user (creates if doesn't exist)
 */
export async function getAnalysisState(
  userId: string
): Promise<AnalysisState | null> {
  const { data, error } = await supabaseAdmin.rpc('get_or_create_analysis_state', {
    p_user_id: userId
  })

  if (error) {
    console.error('Failed to get analysis state:', error)
    throw error
  }

  if (!data || data.length === 0) {
    return null
  }

  const record = data[0]
  return {
    userId: record.user_id,
    lastAnalyzedAt: record.last_analyzed_at,
    lastRunSummary: record.last_run_summary || {},
    createdAt: record.created_at,
    updatedAt: record.updated_at
  }
}

/**
 * Update analysis state after successful run
 */
export async function updateAnalysisState(
  userId: string,
  lastAnalyzedAt: Date,
  runSummary: AnalysisRunSummary
): Promise<void> {
  const { error } = await supabaseAdmin
    .from('ontology_analysis_state')
    .upsert(
      {
        user_id: userId,
        last_analyzed_at: lastAnalyzedAt.toISOString(),
        last_run_summary: runSummary
      },
      {
        onConflict: 'user_id'
      }
    )

  if (error) {
    console.error('Failed to update analysis state:', error)
    throw error
  }
}

/**
 * Record failed analysis run (doesn't update lastAnalyzedAt)
 *
 * IMPORTANT: This function ONLY updates last_run_summary, NOT last_analyzed_at.
 * This ensures failed runs (rate limits, errors) don't mark notes as analyzed.
 *
 * SECURITY FIX: Preserves runCountInWindow to prevent rate limit bypass
 */
export async function recordFailedRun(
  userId: string,
  error: string,
  noteCount: number,
  runCountInWindow?: number
): Promise<void> {
  // Get current state to preserve last_analyzed_at and runCountInWindow
  const currentState = await getAnalysisState(userId)

  // Preserve or increment run count for rate limiting
  const preservedRunCount = runCountInWindow ??
    ((currentState?.lastRunSummary as AnalysisRunSummary & { runCountInWindow?: number })?.runCountInWindow || 1)

  // Only update the summary, explicitly preserving last_analyzed_at and runCountInWindow
  const { error: updateError } = await supabaseAdmin
    .from('ontology_analysis_state')
    .upsert(
      {
        user_id: userId,
        last_analyzed_at: currentState?.lastAnalyzedAt || null, // Preserve existing timestamp
        last_run_summary: {
          triggeredBy: 'manual',
          noteCount,
          status: 'failure',
          error,
          timestamp: new Date().toISOString(),
          runCountInWindow: preservedRunCount
        }
      },
      {
        onConflict: 'user_id'
      }
    )

  if (updateError) {
    console.error('Failed to record failed run:', updateError)
    throw updateError
  }
}

/**
 * Reset analysis state for a user (debug/admin function)
 */
export async function resetAnalysisState(userId: string): Promise<void> {
  const { error } = await supabaseAdmin
    .from('ontology_analysis_state')
    .update({
      last_analyzed_at: null,
      last_run_summary: {}
    })
    .eq('user_id', userId)

  if (error) {
    console.error('Failed to reset analysis state:', error)
    throw error
  }
}

/**
 * Database row shape from get_notes_for_incremental_analysis RPC
 */
interface NoteRPCRow {
  id: string
  user_id: string
  title: string
  content: string
  note_type: string
  is_pinned?: boolean
  metadata: Record<string, unknown>
  created_at: string
  updated_at: string
}

/**
 * Get notes that need to be analyzed (new or updated since last analysis)
 *
 * IMPORTANT: Maps snake_case database fields to camelCase Note interface
 * to ensure maxNoteTimestamp calculation works correctly in the route handler.
 */
export async function getNotesForIncrementalAnalysis(
  userId: string,
  lastAnalyzedAt: Date | null
): Promise<Note[]> {
  const { data, error } = await supabaseAdmin.rpc(
    'get_notes_for_incremental_analysis',
    {
      p_user_id: userId,
      p_last_analyzed_at: lastAnalyzedAt?.toISOString() || null
    }
  )

  if (error) {
    console.error('Failed to get notes for incremental analysis:', error)
    throw error
  }

  // Map snake_case database fields to camelCase Note interface
  // This is critical for maxNoteTimestamp calculation in the route handler
  if (!data) return []

  return (data as NoteRPCRow[]).map((row) => ({
    id: row.id,
    userId: row.user_id,
    title: row.title,
    content: row.content,
    noteType: row.note_type as Note['noteType'],
    isPinned: row.is_pinned || false,
    metadata: row.metadata as Note['metadata'],
    createdAt: row.created_at,
    updatedAt: row.updated_at
  }))
}

/**
 * Check if user needs analysis (has new notes since last run)
 */
export async function needsAnalysis(userId: string): Promise<boolean> {
  const state = await getAnalysisState(userId)

  if (!state || !state.lastAnalyzedAt) {
    // Never analyzed - check if user has any notes
    const notes = await getNotesForIncrementalAnalysis(userId, null)
    return notes.length >= 5 // Minimum threshold
  }

  // Check if there are new notes since last analysis
  const lastAnalyzed = new Date(state.lastAnalyzedAt)
  const newNotes = await getNotesForIncrementalAnalysis(userId, lastAnalyzed)

  return newNotes.length > 0
}

// ============================================================================
// Concurrency Control
// ============================================================================

/**
 * Try to acquire analysis lock for a user
 * Returns true if lock acquired, false if already locked
 *
 * SECURITY: Uses atomic UPDATE to prevent race conditions in concurrent requests
 * SECURITY FIX: Seeds status for new users to prevent lock acquisition failure
 */
export async function tryAcquireLock(userId: string): Promise<boolean> {
  const tenMinutesAgo = new Date()
  tenMinutesAgo.setMinutes(tenMinutesAgo.getMinutes() - 10)

  // Seed empty summaries with a proper status to fix new user lock acquisition
  // Only updates rows where last_run_summary is empty {} (no status field)
  await supabaseAdmin
    .from('ontology_analysis_state')
    .update({
      last_run_summary: { status: 'success', timestamp: new Date(0).toISOString() }
    })
    .eq('user_id', userId)
    .is('last_run_summary->status', null) // Only if status key doesn't exist

  // Atomic lock acquisition: only update if not already locked
  // A row is "locked" if it was updated recently AND has no status (in-progress)
  const { data, error } = await supabaseAdmin
    .from('ontology_analysis_state')
    .update({
      last_run_summary: { timestamp: new Date().toISOString() }
    })
    .eq('user_id', userId)
    // Only acquire lock if either:
    // 1. Last update was old (> 10 minutes ago), OR
    // 2. Last run has a status (success/failure/skipped - not in-progress)
    .or(`updated_at.lt.${tenMinutesAgo.toISOString()},last_run_summary->>status.not.is.null`)
    .select()

  // Lock acquired if we successfully updated a row
  return !error && data && data.length > 0
}

/**
 * Release analysis lock for a user
 *
 * IMPORTANT: This function only updates the summary, NOT lastAnalyzedAt.
 * The caller should have already set lastAnalyzedAt via updateAnalysisState()
 * before calling this function to release the lock.
 */
export async function releaseLock(
  userId: string,
  summary: AnalysisRunSummary
): Promise<void> {
  // Get current state to preserve lastAnalyzedAt
  const currentState = await getAnalysisState(userId)

  // Only update the summary, preserving the lastAnalyzedAt that was set by the caller
  const { error } = await supabaseAdmin
    .from('ontology_analysis_state')
    .upsert(
      {
        user_id: userId,
        last_analyzed_at: currentState?.lastAnalyzedAt || null,
        last_run_summary: summary
      },
      {
        onConflict: 'user_id'
      }
    )

  if (error) {
    console.error('Failed to release lock:', error)
    throw error
  }
}

/**
 * Supabase Admin Client (Service Role)
 *
 * Uses service role key to bypass RLS for backend operations.
 * ONLY use in API routes and server-side code.
 * NEVER expose to client.
 */

import { createClient } from '@supabase/supabase-js'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!
const supabaseServiceRole = process.env.SUPABASE_SERVICE_ROLE_KEY!

if (!supabaseServiceRole) {
  throw new Error('SUPABASE_SERVICE_ROLE_KEY environment variable is required for admin operations')
}

export const supabaseAdmin = createClient(supabaseUrl, supabaseServiceRole, {
  auth: {
    autoRefreshToken: false,
    persistSession: false
  }
})

import { createClient } from '@supabase/supabase-js'

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!

export const supabase = createClient(supabaseUrl, supabaseAnonKey, {
