// ============================================================================
// Helper Functions: Database → App Type Mapping
// ============================================================================

/**
 * Maps database column names to app-friendly camelCase.
 */
function mapDatabaseNoteToNote(dbNote: {
  id: string
  user_id: string
  title: string
  content: string
  note_type: string
  is_pinned: boolean
  metadata: Record<string, unknown>
  created_at: string
  updated_at: string
}): Note {
  return {
    id: dbNote.id,
    userId: dbNote.user_id,
    title: dbNote.title,
    content: dbNote.content,
    noteType: dbNote.note_type as NoteType,
    isPinned: dbNote.is_pinned,
    metadata: dbNote.metadata || {},
    createdAt: dbNote.created_at,
    updatedAt: dbNote.updated_at
  }
}

function mapDatabaseNotesToNotes(dbNotes: Array<{
  id: string
  user_id: string
  title: string
  content: string
  note_type: string
  is_pinned: boolean
  metadata: Record<string, unknown>
  created_at: string
  updated_at: string
}>): Note[] {
  return dbNotes.map(mapDatabaseNoteToNote)
}

function mapDatabaseLinkToLink(dbLink: {
  id: string
  source_note_id: string
  target_note_id: string
  link_type: string
  user_id: string
  metadata?: Record<string, unknown>
  created_at: string
}): Link {
  return {
    id: dbLink.id,
    sourceNoteId: dbLink.source_note_id,
    targetNoteId: dbLink.target_note_id,
    linkType: dbLink.link_type as import('@/types/note').LinkType,
    userId: dbLink.user_id,
    metadata: dbLink.metadata || {},
    createdAt: dbLink.created_at
  }
}

function mapDatabaseLinksToLinks(dbLinks: Array<{
  id: string
  source_note_id: string
  target_note_id: string
  link_type: string
  user_id: string
  metadata?: Record<string, unknown>
  created_at: string
}>): Link[] {
  return dbLinks.map(mapDatabaseLinkToLink)
}

